CREATE OR REPLACE FUNCTION public.split_transaction_by_bp_lines(p_transaction_id uuid, p_lines jsonb, p_changed_by text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tx public.transactions%ROWTYPE; v_n int; v_sum numeric := 0; v_i int; v_item jsonb;
        v_fc record; v_amount numeric; v_group uuid; v_new_id uuid; v_event_status text; v_seen uuid[] := '{}';
BEGIN
  SELECT * INTO v_tx FROM public.transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'transaction_not_found' USING ERRCODE = 'P0002'; END IF;
  IF NOT (public.is_platform_admin(auth.uid())
          OR public.has_role_in(auth.uid(), 'admin', v_tx.company_id)
          OR public.has_role_in(auth.uid(), 'manager', v_tx.company_id)
          OR public.has_permission_in(auth.uid(), 'manage_transactions', v_tx.company_id)) THEN
    RAISE EXCEPTION 'Sem permissão para repartir a transação.' USING ERRCODE = '42501';
  END IF;
  IF v_tx.type <> 'expense' THEN RAISE EXCEPTION 'Só despesas podem ser repartidas por linhas de BP.'; END IF;
  IF v_tx.event_id IS NULL THEN RAISE EXCEPTION 'A transação não tem evento.'; END IF;
  IF coalesce(v_tx.paid_amount,0) > 0 OR v_tx.status IN ('paid','reversed')
     OR EXISTS (SELECT 1 FROM public.transaction_payments WHERE transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'A transação já tem pagamentos — reparte antes de pagar.';
  END IF;
  IF v_tx.parent_transaction_id IS NOT NULL OR v_tx.split_percentage IS NOT NULL
     OR EXISTS (SELECT 1 FROM public.transactions WHERE parent_transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'Transações de rateio entre eventos não podem ser repartidas aqui.';
  END IF;
  IF v_tx.installment_group_id IS NOT NULL THEN RAISE EXCEPTION 'A transação pertence a um parcelamento.'; END IF;
  IF coalesce(v_tx.is_reimbursement,false) OR coalesce(v_tx.is_transitory,false) THEN
    RAISE EXCEPTION 'Reembolsos e transitórias não podem ser repartidos.';
  END IF;
  SELECT status INTO v_event_status FROM public.events WHERE id = v_tx.event_id;
  IF v_event_status = 'completed' THEN RAISE EXCEPTION 'O evento está fechado.'; END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN RAISE EXCEPTION 'Lista de linhas inválida.'; END IF;
  v_n := jsonb_array_length(p_lines);
  IF v_n < 2 THEN RAISE EXCEPTION 'São precisas pelo menos 2 linhas de BP.'; END IF;

  FOR v_i IN 0..v_n-1 LOOP
    v_item := p_lines -> v_i;
    v_amount := round((v_item->>'amount')::numeric, 2);
    IF v_amount IS NULL OR v_amount <= 0 THEN RAISE EXCEPTION 'Linha % com valor inválido.', v_i+1; END IF;
    SELECT id, event_id, category_id, type, version_id, company_id INTO v_fc
      FROM public.event_forecasts WHERE id = (v_item->>'forecast_id')::uuid;
    IF NOT FOUND OR v_fc.event_id <> v_tx.event_id OR v_fc.company_id <> v_tx.company_id
       OR v_fc.version_id IS NOT NULL OR v_fc.type <> 'expense' THEN
      RAISE EXCEPTION 'Linha % não é uma linha de despesa do BP vivo deste evento.', v_i+1;
    END IF;
    IF v_fc.id = ANY(v_seen) THEN RAISE EXCEPTION 'Linha de BP repetida.'; END IF;
    v_seen := v_seen || v_fc.id;
    v_sum := v_sum + v_amount;
  END LOOP;
  IF abs(v_sum - v_tx.amount) > 0.01 THEN
    RAISE EXCEPTION 'A soma das partes (% €) tem de igualar o valor da transação (% €, s/IVA).', v_sum, v_tx.amount;
  END IF;

  v_group := coalesce(v_tx.invoice_group_id, gen_random_uuid());

  FOR v_i IN 0..v_n-1 LOOP
    v_item := p_lines -> v_i;
    v_amount := round((v_item->>'amount')::numeric, 2);
    SELECT id, category_id INTO v_fc FROM public.event_forecasts WHERE id = (v_item->>'forecast_id')::uuid;
    IF v_i = 0 THEN
      UPDATE public.transactions
         SET amount = v_amount, forecast_id = v_fc.id, category_id = v_fc.category_id,
             invoice_group_id = v_group,
             original_amount = CASE WHEN coalesce(v_tx.currency,'EUR') <> 'EUR' AND v_tx.original_amount IS NOT NULL AND v_tx.amount <> 0
                                    THEN round(v_tx.original_amount * v_amount / v_tx.amount, 2) ELSE v_tx.original_amount END,
             updated_at = now()
       WHERE id = p_transaction_id;
      INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value) VALUES
        (p_transaction_id, p_changed_by, 'Valor (repartir por linhas de BP)', round(v_tx.amount,2)::text, v_amount::text),
        (p_transaction_id, p_changed_by, 'Linha de BP (repartir)', coalesce(v_tx.forecast_id::text,''), v_fc.id::text);
    ELSE
      INSERT INTO public.transactions (
        description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
        specification, date, due_date, status, paid_amount, payment_date,
        is_reimbursement, is_transitory, exclude_from_result,
        invoice_ref, invoice_group_id, payment_method, payment_entity, payment_reference, operation_key,
        ordering_partner_id, paying_partner_id, currency, fx_rate, fx_rate_source, original_amount, company_id
      ) VALUES (
        v_tx.description, v_tx.type, v_amount, v_tx.iva_rate, v_tx.event_id, v_fc.category_id, v_fc.id, v_tx.supplier_id, v_tx.account_id,
        v_tx.specification, v_tx.date, v_tx.due_date, v_tx.status, 0, NULL,
        false, false, coalesce(v_tx.exclude_from_result,false),
        v_tx.invoice_ref, v_group, v_tx.payment_method, v_tx.payment_entity, v_tx.payment_reference, v_tx.operation_key,
        v_tx.ordering_partner_id, v_tx.paying_partner_id, coalesce(v_tx.currency,'EUR'), v_tx.fx_rate, v_tx.fx_rate_source,
        CASE WHEN coalesce(v_tx.currency,'EUR') <> 'EUR' AND v_tx.original_amount IS NOT NULL AND v_tx.amount <> 0
             THEN round(v_tx.original_amount * v_amount / v_tx.amount, 2) ELSE NULL END,
        v_tx.company_id
      ) RETURNING id INTO v_new_id;
      INSERT INTO public.transaction_documents (transaction_id, name, file_url, doc_type, uploaded_by, uploaded_at, is_accounting, company_id, partner_visible)
        SELECT v_new_id, name, file_url, doc_type, uploaded_by, uploaded_at, is_accounting, company_id, partner_visible
          FROM public.transaction_documents WHERE transaction_id = p_transaction_id;
      INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
        VALUES (v_new_id, p_changed_by, 'Criação (repartir por linhas de BP)', p_transaction_id::text, v_amount::text || ' € (base) → linha ' || v_fc.id::text);
    END IF;
  END LOOP;
  RETURN v_group;
END $function$

CREATE OR REPLACE FUNCTION public._cache_create_contract(p_uid uuid, p_root uuid, p_artist uuid, p_beneficiary uuid, p_gross numeric, p_wh_applies boolean, p_wh_rate numeric, p_wh_due date, p_artist_due date, p_advance_ids uuid[], p_label text, p_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid := public.current_company_id();
  v_cat uuid; v_at uuid; v_cid uuid; v_n int; v_absorber int;
  v_ids uuid[]; v_events uuid[]; v_names text[]; v_lines uuid[]; v_caps numeric[]; v_abs boolean[];
  v_total_cap numeric := 0; v_used numeric; v_free_other numeric;
  v_quota numeric[]; v_wh numeric[]; v_adv numeric[]; v_art numeric[];
  v_W numeric := 0; v_sum_art numeric := 0; v_sum_adv numeric := 0;
  v_mother uuid; v_wh_mother uuid; v_pct numeric; v_acc numeric; v_first_idx int;
  v_desc_artist text; v_artist_name text; v_contract_no int;
  r record; i int; v_city_other numeric; v_city_free numeric; v_today date := (now() AT TIME ZONE 'Europe/Lisbon')::date;
BEGIN
  IF p_key IS NOT NULL THEN
    SELECT id INTO v_cid FROM public.cache_payment_contracts WHERE company_id = v_company AND idempotency_key = p_key;
    IF FOUND THEN RETURN v_cid; END IF;
  END IF;
  IF p_wh_applies IS NULL THEN RAISE EXCEPTION 'retencao_sem_resposta: responda Sim ou Não à retenção IRS'; END IF;
  IF p_wh_applies AND (p_wh_rate IS NULL OR p_wh_rate <= 0 OR p_wh_rate >= 100) THEN RAISE EXCEPTION 'taxa_invalida: taxa de retenção inválida'; END IF;
  IF p_wh_applies AND p_wh_due IS NULL THEN RAISE EXCEPTION 'vencimento_retencao_obrigatorio: indique o vencimento da retenção'; END IF;
  IF p_gross IS NULL OR p_gross <= 0 OR p_gross <> round(p_gross,2) THEN RAISE EXCEPTION 'bruto_invalido: valor bruto inválido'; END IF;
  IF p_beneficiary IS NULL OR NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id = p_beneficiary AND company_id = v_company) THEN
    RAISE EXCEPTION 'beneficiario_invalido: escolha o beneficiário desta empresa';
  END IF;

  SELECT count(*) INTO v_n FROM public.cache_payment_contracts
   WHERE root_event_id = p_root AND artist_supplier_id = p_artist AND cancelled_at IS NULL;
  IF v_n >= public.cache_max_contracts() THEN
    RAISE EXCEPTION 'limite_contratos: máximo de % contratos por cachê', public.cache_max_contracts();
  END IF;
  v_contract_no := v_n + 1;

  v_cat := public._cache_category(v_company);
  IF v_cat IS NULL THEN RAISE EXCEPTION 'categoria_em_falta: rubrica 2.1.01 não existe nesta empresa'; END IF;
  SELECT name INTO v_artist_name FROM public.suppliers WHERE id = p_artist;

  SELECT array_agg(event_id ORDER BY idx), array_agg(event_name ORDER BY idx), array_agg(forecast_id ORDER BY idx),
         array_agg(cap ORDER BY idx), array_agg(is_absorber ORDER BY idx)
    INTO v_events, v_names, v_lines, v_caps, v_abs
    FROM public._cache_cities(p_root, p_artist);
  IF v_events IS NULL THEN RAISE EXCEPTION 'sem_linha_cache: não há linha do cachê no BP das cidades; sincronize o cachê primeiro'; END IF;
  IF (SELECT count(DISTINCT e) FROM unnest(v_events) e) <> array_length(v_events,1) THEN
    RAISE EXCEPTION 'linha_cache_duplicada: uma cidade tem mais de uma linha do cachê deste artista';
  END IF;
  v_n := array_length(v_events,1);
  FOR i IN 1..v_n LOOP v_total_cap := v_total_cap + v_caps[i]; IF v_abs[i] THEN v_absorber := i; END IF; END LOOP;
  IF v_total_cap <= 0 THEN RAISE EXCEPTION 'cache_sem_valor: cachê efetivo é zero'; END IF;

  v_ids := coalesce((SELECT array_agg(DISTINCT x) FROM unnest(p_advance_ids) x), '{}');
  v_adv := array_fill(0::numeric, ARRAY[v_n]);
  FOR r IN SELECT t.* FROM public.transactions t WHERE t.id = ANY(v_ids) ORDER BY t.id FOR UPDATE LOOP NULL; END LOOP;
  IF (SELECT count(*) FROM public.transactions t WHERE t.id = ANY(v_ids)) <> coalesce(array_length(v_ids,1),0) THEN
    RAISE EXCEPTION 'adiantamento_inexistente';
  END IF;
  IF EXISTS (SELECT 1 FROM public.transactions t WHERE t.id = ANY(v_ids) AND t.cache_contract_id IS NOT NULL) THEN
    RAISE EXCEPTION 'adiantamento_ja_associado: um adiantamento já pertence a outro contrato';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_ids) x WHERE x NOT IN (SELECT tx_id FROM public._cache_free_advances(p_root, p_artist))) THEN
    RAISE EXCEPTION 'adiantamento_invalido: só adiantamentos livres do cachê nas cidades (não lançados no Master)';
  END IF;
  FOR r IN SELECT fa.event_id, sum(fa.amount) AS amt FROM public._cache_free_advances(p_root, p_artist) fa
            WHERE fa.tx_id = ANY(v_ids) GROUP BY fa.event_id LOOP
    i := array_position(v_events, r.event_id);
    v_adv[i] := v_adv[i] + r.amt; v_sum_adv := v_sum_adv + r.amt;
  END LOOP;

  SELECT coalesce(sum(gross),0) INTO v_used FROM public.cache_payment_contracts
   WHERE root_event_id = p_root AND artist_supplier_id = p_artist AND cancelled_at IS NULL;
  SELECT coalesce(sum(amount),0) INTO v_free_other FROM public._cache_free_advances(p_root, p_artist) WHERE NOT (tx_id = ANY(v_ids));
  IF p_gross + v_used + v_free_other > v_total_cap + 0.005 THEN
    RAISE EXCEPTION 'teto_excedido: bruto % excede o restante por contratar % (cachê efetivo %)',
      p_gross, v_total_cap - v_used - v_free_other, v_total_cap;
  END IF;

  v_quota := public._cache_alloc(p_gross, v_caps, v_absorber);
  IF p_wh_applies THEN
    v_W := round(p_gross * p_wh_rate / 100, 2);
    v_wh := public._cache_alloc(v_W, v_caps, v_absorber);
  ELSE
    v_wh := array_fill(0::numeric, ARRAY[v_n]);
  END IF;
  v_art := array_fill(0::numeric, ARRAY[v_n]);
  FOR i IN 1..v_n LOOP
    v_art[i] := v_quota[i] - v_wh[i] - v_adv[i];
    IF v_art[i] < 0 THEN
      RAISE EXCEPTION 'saldo_negativo: em % os adiantamentos (%) excedem a quota líquida (%) — saldo %',
        v_names[i], v_adv[i], v_quota[i] - v_wh[i], v_art[i];
    END IF;
    SELECT coalesce(sum(cc.quota),0) INTO v_city_other FROM public.cache_payment_contract_cities cc
      JOIN public.cache_payment_contracts k ON k.id = cc.contract_id
     WHERE k.root_event_id = p_root AND k.artist_supplier_id = p_artist AND k.cancelled_at IS NULL AND cc.event_id = v_events[i];
    SELECT coalesce(sum(amount),0) INTO v_city_free FROM public._cache_free_advances(p_root, p_artist)
     WHERE event_id = v_events[i] AND NOT (tx_id = ANY(v_ids));
    IF v_city_other + v_quota[i] + v_city_free > v_caps[i] + 0.005 THEN
      RAISE EXCEPTION 'teto_cidade_excedido: % ficaria com % acima do cachê da cidade %', v_names[i], v_city_other + v_quota[i] + v_city_free, v_caps[i];
    END IF;
    v_sum_art := v_sum_art + v_art[i];
  END LOOP;

  INSERT INTO public.cache_payment_contracts(company_id, root_event_id, artist_supplier_id, beneficiary_supplier_id, label, gross,
      withholding_applies, withholding_rate, withholding_amount, withholding_due_date, artist_due_date, advances_amount, idempotency_key, created_by)
  VALUES (v_company, p_root, p_artist, p_beneficiary, nullif(trim(p_label),''), p_gross,
      p_wh_applies, CASE WHEN p_wh_applies THEN p_wh_rate END, v_W, p_wh_due, p_artist_due, v_sum_adv, p_key, p_uid)
  RETURNING id INTO v_cid;

  FOR i IN 1..v_n LOOP
    INSERT INTO public.cache_payment_contract_cities(contract_id, company_id, event_id, forecast_id, cap, quota, withholding, advances, artist_balance, is_absorber)
    VALUES (v_cid, v_company, v_events[i], v_lines[i], v_caps[i], v_quota[i], v_wh[i], v_adv[i], v_art[i], i = v_absorber);
  END LOOP;

  v_desc_artist := 'Cachê ' || coalesce(v_artist_name,'') || ' — contrato ' || v_contract_no || coalesce(' (' || nullif(trim(p_label),'') || ')','');

  IF v_sum_art > 0 THEN
    INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
        date, due_date, status, paid_amount, split_mode, company_id, cache_contract_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
    VALUES (v_desc_artist || ' — saldo', 'expense', v_sum_art, 0, NULL, v_cat, NULL, p_beneficiary, NULL,
        v_today, p_artist_due, 'approved', 0, 'percentage', v_company, v_cid, 'artist_balance', p_root, p_artist)
    RETURNING id INTO v_mother;
    v_acc := 0; v_first_idx := NULL;
    FOR i IN 1..v_n LOOP
      IF v_art[i] > 0 THEN
        IF v_first_idx IS NULL OR v_art[i] > v_art[v_first_idx] THEN v_first_idx := i; END IF;
      END IF;
    END LOOP;
    FOR i IN 1..v_n LOOP
      IF v_art[i] > 0 THEN
        v_pct := CASE WHEN i = v_first_idx THEN NULL ELSE round(v_art[i] / v_sum_art * 100, 4) END;
        IF v_pct IS NOT NULL THEN v_acc := v_acc + v_pct; END IF;
      END IF;
    END LOOP;
    FOR i IN 1..v_n LOOP
      IF v_art[i] > 0 THEN
        INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
            date, due_date, status, paid_amount, parent_transaction_id, split_percentage, split_mode, company_id,
            cache_contract_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
        VALUES (v_desc_artist || ' — saldo', 'expense', v_art[i], 0, v_events[i], v_cat, v_lines[i], p_beneficiary, NULL,
            v_today, p_artist_due, 'approved', 0, v_mother,
            CASE WHEN i = v_first_idx THEN 100 - v_acc ELSE round(v_art[i] / v_sum_art * 100, 4) END,
            'percentage', v_company, v_cid, 'artist_balance', p_root, p_artist);
      END IF;
    END LOOP;
  END IF;

  IF p_wh_applies AND v_W > 0 THEN
    SELECT id INTO v_at FROM public.suppliers WHERE company_id = v_company AND name = 'MINISTERIO DAS FINANCAS - IRS' LIMIT 1;
    IF v_at IS NULL THEN RAISE EXCEPTION 'fornecedor_at_em_falta: crie o fornecedor MINISTERIO DAS FINANCAS - IRS nesta empresa'; END IF;
    INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
        date, due_date, status, paid_amount, split_mode, company_id, cache_contract_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
    VALUES ('Retenção IRS ' || p_wh_rate || '% — ' || v_desc_artist, 'expense', v_W, 0, NULL, v_cat, NULL, v_at, NULL,
        v_today, p_wh_due, 'approved', 0, 'percentage', v_company, v_cid, 'withholding', p_root, p_artist)
    RETURNING id INTO v_wh_mother;
    v_acc := 0;
    FOR i IN 1..v_n LOOP
      IF v_wh[i] > 0 AND i <> v_absorber THEN v_acc := v_acc + round(v_wh[i] / v_W * 100, 4); END IF;
    END LOOP;
    FOR i IN 1..v_n LOOP
      IF v_wh[i] > 0 THEN
        INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
            date, due_date, status, paid_amount, parent_transaction_id, split_percentage, split_mode, company_id,
            cache_contract_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
        VALUES ('Retenção IRS ' || p_wh_rate || '% — ' || v_desc_artist, 'expense', v_wh[i], 0, v_events[i], v_cat, v_lines[i], v_at, NULL,
            v_today, p_wh_due, 'approved', 0, v_wh_mother,
            CASE WHEN i = v_absorber THEN 100 - v_acc ELSE round(v_wh[i] / v_W * 100, 4) END,
            'percentage', v_company, v_cid, 'withholding', p_root, p_artist);
      END IF;
    END LOOP;
  END IF;

  UPDATE public.cache_payment_contracts SET artist_mother_id = v_mother, withholding_mother_id = v_wh_mother WHERE id = v_cid;

  IF array_length(v_ids,1) > 0 THEN
    UPDATE public.transactions SET cache_contract_id = v_cid, cache_role = 'advance',
           cache_root_event_id = p_root, cache_artist_supplier_id = p_artist
     WHERE id = ANY(v_ids) OR parent_transaction_id = ANY(v_ids);
  END IF;
  RETURN v_cid;
END $function$

CREATE OR REPLACE FUNCTION public.save_ticket_office_settlement(p_settlement_id uuid, p_payload jsonb, p_confirm boolean, p_selected jsonb, p_transfer jsonb, p_retained_payment_notes text, p_remainder_payment_notes text, p_audit_user text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_company uuid;
  v_id uuid;
  v_prev public.ticket_office_settlements%ROWTYPE;
  v_has_prev boolean := false;
  v_office uuid := (p_payload->>'financial_account_id')::uuid;
  v_event uuid := nullif(p_payload->>'event_id','')::uuid;
  v_date date := (p_payload->>'settlement_date')::date;
  v_ids uuid[];
  v_ret_amt numeric := coalesce((p_payload->>'venue_retained_amount')::numeric, 0);
  v_inv uuid := nullif(p_payload->>'venue_retained_invoice_id','')::uuid;
  v_rem_applied boolean := coalesce((p_payload->>'venue_invoice_remainder_paid')::boolean, false);
  v_rem_amt numeric := coalesce((p_payload->>'venue_invoice_remainder_amount')::numeric, 0);
  v_need_rev boolean;
  v_need_rev_rem boolean;
  v_tx record;
  v_pay uuid;
  r record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão obrigatória' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.has_role(v_uid, 'admin') OR public.is_platform_admin(v_uid)
          OR public.has_permission(v_uid, 'manage_accounts')) THEN
    RAISE EXCEPTION 'Sem permissão para gravar o fecho de bilheteira' USING ERRCODE = '42501';
  END IF;
  v_company := public.current_company_id();
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Empresa activa não resolvida' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = v_office AND company_id = v_company) THEN
    RAISE EXCEPTION 'Bilheteira de outra empresa' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(array_agg((x->>'id')::uuid), '{}') INTO v_ids FROM jsonb_array_elements(coalesce(p_selected,'[]'::jsonb)) x;
  IF EXISTS (SELECT 1 FROM public.transactions t WHERE t.id = ANY(v_ids) AND t.company_id IS DISTINCT FROM v_company) THEN
    RAISE EXCEPTION 'Dedução de outra empresa' USING ERRCODE = '42501';
  END IF;
  IF v_inv IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.transactions WHERE id = v_inv AND company_id = v_company) THEN
    RAISE EXCEPTION 'Fatura de outra empresa' USING ERRCODE = '42501';
  END IF;

  IF p_settlement_id IS NOT NULL THEN
    SELECT * INTO v_prev FROM public.ticket_office_settlements WHERE id = p_settlement_id FOR UPDATE;
    IF v_prev.id IS NULL OR v_prev.company_id IS DISTINCT FROM v_company THEN
      RAISE EXCEPTION 'Fecho não encontrado nesta empresa' USING ERRCODE = '42501';
    END IF;
    v_has_prev := true;
    v_id := p_settlement_id;
    UPDATE public.ticket_office_settlements SET
      financial_account_id = v_office, event_id = v_event, settlement_date = v_date,
      gross_revenue = (p_payload->>'gross_revenue')::numeric,
      total_deductions = (p_payload->>'total_deductions')::numeric,
      net_calculated = (p_payload->>'net_calculated')::numeric,
      net_adjusted = nullif(p_payload->>'net_adjusted','')::numeric,
      adjustment_notes = p_payload->>'adjustment_notes',
      gross_adjustment_notes = p_payload->>'gross_adjustment_notes',
      forma_liquidacao_manual = p_payload->>'forma_liquidacao_manual',
      forma_liquidacao_manual_notes = p_payload->>'forma_liquidacao_manual_notes',
      net_transferred = coalesce((p_payload->>'net_transferred')::numeric, 0),
      transfer_account_id = nullif(p_payload->>'transfer_account_id','')::uuid,
      document_url = p_payload->>'document_url',
      document_name = p_payload->>'document_name',
      notes = p_payload->>'notes',
      venue_retained_amount = v_ret_amt,
      venue_retained_invoice_id = v_inv,
      venue_retained_notes = p_payload->>'venue_retained_notes',
      venue_invoice_remainder_paid = v_rem_applied,
      venue_invoice_remainder_amount = v_rem_amt,
      status = CASE WHEN p_confirm THEN 'confirmed' ELSE 'draft' END,
      closed_at = CASE WHEN p_confirm THEN now() ELSE closed_at END,
      closed_by = CASE WHEN p_confirm THEN v_uid ELSE closed_by END
    WHERE id = v_id;
  ELSE
    INSERT INTO public.ticket_office_settlements (
      company_id, financial_account_id, event_id, settlement_date, gross_revenue, total_deductions,
      net_calculated, net_adjusted, adjustment_notes, gross_adjustment_notes,
      forma_liquidacao_manual, forma_liquidacao_manual_notes, net_transferred, transfer_account_id,
      document_url, document_name, notes, venue_retained_amount, venue_retained_invoice_id,
      venue_retained_notes, venue_invoice_remainder_paid, venue_invoice_remainder_amount,
      status, closed_at, closed_by, created_by
    ) VALUES (
      v_company, v_office, v_event, v_date, (p_payload->>'gross_revenue')::numeric,
      (p_payload->>'total_deductions')::numeric, (p_payload->>'net_calculated')::numeric,
      nullif(p_payload->>'net_adjusted','')::numeric, p_payload->>'adjustment_notes',
      p_payload->>'gross_adjustment_notes', p_payload->>'forma_liquidacao_manual',
      p_payload->>'forma_liquidacao_manual_notes', coalesce((p_payload->>'net_transferred')::numeric, 0),
      nullif(p_payload->>'transfer_account_id','')::uuid, p_payload->>'document_url',
      p_payload->>'document_name', p_payload->>'notes', v_ret_amt, v_inv,
      p_payload->>'venue_retained_notes', v_rem_applied, v_rem_amt,
      CASE WHEN p_confirm THEN 'confirmed' ELSE 'draft' END,
      CASE WHEN p_confirm THEN now() END, CASE WHEN p_confirm THEN v_uid END, v_uid
    ) RETURNING id INTO v_id;
  END IF;

  IF p_confirm AND p_transfer IS NOT NULL AND coalesce((p_transfer->>'amount')::numeric,0) > 0
     AND NOT (v_has_prev AND v_prev.transfer_transaction_id IS NOT NULL) THEN
    PERFORM public.create_settlement_transfer(v_id, v_office, (p_transfer->>'to_account_id')::uuid,
      (p_transfer->>'amount')::numeric, v_date, coalesce((p_transfer->>'credited')::boolean, false));
  END IF;

  IF v_has_prev THEN
    UPDATE public.transactions t SET settlement_id = NULL
     WHERE t.settlement_id = v_id
       AND NOT (t.id = ANY(v_ids))
       AND t.id IS DISTINCT FROM (SELECT transfer_transaction_id FROM public.ticket_office_settlements WHERE id = v_id)
       AND coalesce(t.operation_key,'') NOT LIKE 'TRF-FECHO-%';
  END IF;

  IF array_length(v_ids,1) > 0 THEN
    IF p_confirm THEN
      FOR r IN SELECT (x->>'id')::uuid AS id, (x->>'paid_amount')::numeric AS paid
                 FROM jsonb_array_elements(p_selected) x LOOP
        IF r.paid IS NULL THEN
          UPDATE public.transactions SET settlement_id = v_id WHERE id = r.id;
          CONTINUE;
        END IF;
        SELECT id, reversed_at INTO v_tx FROM public.transactions WHERE id = r.id FOR UPDATE;
        IF v_tx.id IS NULL THEN RAISE EXCEPTION 'Dedução % não encontrada', r.id; END IF;
        UPDATE public.transactions SET settlement_id = v_id, status = 'paid', payment_date = v_date,
               account_id = v_office, paid_amount = r.paid,
               reversed_at = CASE WHEN v_tx.reversed_at IS NOT NULL THEN NULL ELSE reversed_at END,
               reversal_kind = CASE WHEN v_tx.reversed_at IS NOT NULL THEN NULL ELSE reversal_kind END
         WHERE id = r.id;
        IF v_tx.reversed_at IS NOT NULL THEN
          INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
          VALUES (r.id, p_audit_user, 'Estorno', 'Estornada em ' || to_char(v_tx.reversed_at, 'YYYY-MM-DD'),
                  'Carimbo de estorno limpo — transação voltou a ser paga');
        END IF;
      END LOOP;
    ELSE
      UPDATE public.transactions SET settlement_id = v_id WHERE id = ANY(v_ids);
    END IF;
  END IF;

  v_need_rev := v_has_prev AND v_prev.venue_retained_payment_id IS NOT NULL AND (
    NOT p_confirm OR v_inv IS NULL OR v_inv IS DISTINCT FROM v_prev.venue_retained_invoice_id
    OR abs(v_ret_amt - coalesce(v_prev.venue_retained_amount,0)) > 0.005);
  IF v_need_rev THEN
    DELETE FROM public.transaction_payments WHERE id = v_prev.venue_retained_payment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pagamento de compensação anterior não encontrado'; END IF;
    UPDATE public.ticket_office_settlements SET venue_retained_payment_id = NULL WHERE id = v_id;
  END IF;

  IF p_confirm AND v_ret_amt > 0 AND v_inv IS NOT NULL
     AND (v_need_rev OR NOT v_has_prev OR v_prev.venue_retained_payment_id IS NULL) THEN
    INSERT INTO public.transaction_payments (transaction_id, amount, payment_date, payment_method, account_id, notes, created_by)
    VALUES (v_inv, v_ret_amt, v_date, 'compensation', NULL, p_retained_payment_notes, p_audit_user)
    RETURNING id INTO v_pay;
    UPDATE public.ticket_office_settlements SET venue_retained_payment_id = v_pay WHERE id = v_id;
  END IF;

  v_need_rev_rem := v_has_prev AND v_prev.venue_invoice_remainder_payment_id IS NOT NULL AND (
    NOT p_confirm OR NOT v_rem_applied OR v_inv IS NULL
    OR v_inv IS DISTINCT FROM v_prev.venue_retained_invoice_id
    OR abs(v_rem_amt - coalesce(v_prev.venue_invoice_remainder_amount,0)) > 0.005);
  IF v_need_rev_rem THEN
    DELETE FROM public.transaction_payments WHERE id = v_prev.venue_invoice_remainder_payment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pagamento do saldo restante anterior não encontrado'; END IF;
    UPDATE public.ticket_office_settlements SET venue_invoice_remainder_payment_id = NULL WHERE id = v_id;
  END IF;

  IF p_confirm AND v_rem_applied AND v_inv IS NOT NULL
     AND (v_need_rev_rem OR NOT v_has_prev OR v_prev.venue_invoice_remainder_payment_id IS NULL) THEN
    INSERT INTO public.transaction_payments (transaction_id, amount, payment_date, payment_method, account_id, notes, created_by)
    VALUES (v_inv, v_rem_amt, v_date, 'transfer', v_office, p_remainder_payment_notes, p_audit_user)
    RETURNING id INTO v_pay;
    UPDATE public.ticket_office_settlements SET venue_invoice_remainder_payment_id = v_pay WHERE id = v_id;
  END IF;

  IF p_confirm AND v_event IS NOT NULL THEN
    UPDATE public.event_ticket_office_assignments
       SET is_conciliated = true, conciliated_at = now(), conciliated_by = coalesce(nullif(p_payload->>'conciliated_by',''), 'system')
     WHERE event_id = v_event AND financial_account_id = v_office;
  END IF;

  RETURN jsonb_build_object('settlement_id', v_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_bank_line(p_line_id uuid, p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_line public.bank_statement_lines;
  v_current uuid;
  v_email text;
  v_sign_type text;
  v_target numeric;
  v_sum numeric := 0;
  v_n int;
  v_item jsonb;
  v_tx public.transactions;
  v_tx_id uuid;
  v_mode text;
  v_amount numeric;
  v_gross numeric;
  v_open numeric;
  v_ids uuid[] := '{}';
  v_pay_date date;
  v_rows int;
  v_action text;
  v_sys_date date;
  v_pending jsonb := '[]'::jsonb;
  v_kept jsonb := '[]'::jsonb;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Nada a conciliar: p_items tem de ser um array com pelo menos um item.';
  end if;

  select * into v_line from public.bank_statement_lines where id = p_line_id;
  if v_line.id is null then
    raise exception 'Linha do banco inexistente ou sem acesso: %', p_line_id;
  end if;

  v_current := public.current_company_id();
  if v_current is null or v_current <> v_line.company_id then
    raise exception 'A linha do banco pertence a outra empresa (%) — empresa activa %.', v_line.company_id, v_current;
  end if;

  if v_line.status <> 'unmatched'
     or v_line.matched_transaction_id is not null
     or v_line.created_transaction_id is not null
     or exists (select 1 from public.bank_line_transactions b where b.line_id = v_line.id) then
    raise exception 'Linha do banco já está conciliada: %', v_line.id;
  end if;

  v_sign_type := case when v_line.amount >= 0 then 'income' else 'expense' end;
  v_target := round(abs(coalesce(v_line.amount, 0))::numeric, 2);
  v_pay_date := coalesce(v_line.value_date, v_line.booking_date);

  v_email := coalesce(
    nullif(auth.jwt() ->> 'email', ''),
    (select p.email from public.profiles p where p.id = auth.uid()),
    'sistema'
  );

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_tx_id := nullif(v_item ->> 'transaction_id', '')::uuid;
    v_mode := coalesce(v_item ->> 'mode', 'link');
    v_amount := round(coalesce((v_item ->> 'amount')::numeric, 0), 2);
    v_action := nullif(v_item ->> 'date_action', '');

    if v_tx_id is null then
      raise exception 'Item sem transaction_id.';
    end if;
    if v_mode not in ('link', 'settle') then
      raise exception 'Modo inválido (%) — só "link" ou "settle".', v_mode;
    end if;
    if v_action is not null and v_action not in ('align', 'keep') then
      raise exception 'date_action inválida (%) — só "align" ou "keep".', v_action;
    end if;
    if v_amount <= 0 then
      raise exception 'Valor inválido para a transação %: %.', v_tx_id, v_amount;
    end if;
    if v_tx_id = any(v_ids) then
      raise exception 'Transação repetida no mesmo pedido: %', v_tx_id;
    end if;

    select * into v_tx from public.transactions where id = v_tx_id;
    if v_tx.id is null then
      raise exception 'Transação inexistente ou sem acesso: %', v_tx_id;
    end if;
    if v_tx.company_id <> v_current then
      raise exception 'A transação % pertence a outra empresa.', v_tx_id;
    end if;
    if v_tx.reversed_at is not null then
      raise exception 'A transação % está revertida.', v_tx_id;
    end if;
    if v_tx.type <> v_sign_type then
      raise exception 'Sinal incompatível: a linha do banco é % e a transação % é "%".',
        case when v_sign_type = 'income' then 'a crédito (receita)' else 'a débito (despesa)' end,
        v_tx_id, v_tx.type;
    end if;

    if v_mode = 'link' then
      -- #233: a data no sistema tem de bater com a do banco, ou a pessoa decide.
      v_sys_date := coalesce(v_tx.payment_date,
        (select max(tp.payment_date) from public.transaction_payments tp
          where tp.transaction_id = v_tx_id and tp.status = 'paid'));
      if v_pay_date is not null and v_sys_date is distinct from v_pay_date then
        if v_action is null then
          v_pending := v_pending || jsonb_build_object('transaction_id', v_tx_id, 'system_date', v_sys_date,
                                                      'bank_date', v_pay_date, 'amount', v_amount);
        elsif v_action = 'align' then
          update public.transaction_payments
             set payment_date = v_pay_date, updated_at = now()
           where transaction_id = v_tx_id and status = 'paid' and payment_date is not distinct from v_sys_date;
          get diagnostics v_rows = row_count;
          if v_rows = 0 then
            update public.transactions set payment_date = v_pay_date where id = v_tx_id;
          end if;
          insert into public.transaction_audit_log (transaction_id, changed_by, changed_at, field_name, old_value, new_value, company_id)
          values (v_tx_id, v_email, now(), 'payment_date', v_sys_date::text,
                  v_pay_date::text || ' (alinhada pela data do banco, #233)', v_current);
        else
          v_kept := v_kept || jsonb_build_object('transaction_id', v_tx_id, 'system_date', v_sys_date,
                     'bank_date', v_pay_date, 'amount', v_amount, 'accepted_by', v_email, 'accepted_at', now());
        end if;
      end if;
    end if;

    if v_mode = 'settle' then
      v_gross := round(coalesce(v_tx.amount, 0) * (1 + coalesce(v_tx.iva_rate, 0) / 100.0), 2);
      v_open := round(v_gross - coalesce(v_tx.paid_amount, 0), 2);
      if v_open <= 0 then
        raise exception 'A transação % não tem valor em aberto.', v_tx_id;
      end if;
      if v_amount > v_open + 0.01 then
        raise exception 'Valor a liquidar (%) acima do que está em aberto (%) na transação %.', v_amount, v_open, v_tx_id;
      end if;

      insert into public.transaction_payments
        (transaction_id, amount, payment_date, account_id, payment_method,
         payment_reference, notes, created_by)
      values
        (v_tx_id, v_amount, v_pay_date, v_line.financial_account_id, 'transfer',
         left(coalesce(v_line.description, ''), 500), 'Liquidação pela conciliação bancária', v_email);

      if v_tx.account_id is null then
        update public.transactions set account_id = v_line.financial_account_id where id = v_tx_id;
      end if;
    end if;

    v_ids := v_ids || v_tx_id;
    v_sum := v_sum + v_amount;
  end loop;

  if jsonb_array_length(v_pending) > 0 then
    raise exception 'Data de pagamento diferente da do banco — escolher alinhar ou manter.'
      using errcode = 'P0410', detail = v_pending::text;
  end if;

  v_sum := round(v_sum, 2);
  if abs(v_sum - v_target) > 0.01 then
    raise exception 'A soma dos valores (%) não bate com a linha do banco (%).', v_sum, v_target;
  end if;

  v_n := array_length(v_ids, 1);

  update public.bank_statement_lines
     set status = 'matched',
         matched_transaction_id = case when v_n = 1 then v_ids[1] else null end,
         matched_payment_list_id = null,
         matched_sepa_export_id = null,
         matched_by = case when v_n = 1 then 'manual:' else 'manual-multi:' end || v_email,
         matched_at = now(),
         date_divergence = case when jsonb_array_length(v_kept) > 0 then v_kept else null end
   where id = v_line.id;

  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'A linha do banco não ficou conciliada.';
  end if;

  delete from public.bank_line_transactions where line_id = v_line.id;
  if v_n > 1 then
    insert into public.bank_line_transactions (line_id, transaction_id)
    select v_line.id, x from unnest(v_ids) x;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_payment(p_payment_id uuid, p_kind text, p_reason text, p_valid_until date DEFAULT NULL::date, p_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_payment public.transaction_payments%ROWTYPE;
  v_tx public.transactions%ROWTYPE;
  v_credit_id uuid;
  v_credit_amount numeric;
BEGIN
  IF NOT public.has_role(v_uid, 'admin'::app_role) THEN
    RAISE EXCEPTION 'permission_denied: apenas administradores podem estornar pagamentos';
  END IF;

  IF p_kind NOT IN ('cash_refund','supplier_credit') THEN
    RAISE EXCEPTION 'invalid_kind: % (esperado cash_refund | supplier_credit)', p_kind;
  END IF;

  IF coalesce(trim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'reason_required: motivo do estorno é obrigatório';
  END IF;

  SELECT * INTO v_payment FROM public.transaction_payments WHERE id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found: %', p_payment_id;
  END IF;

  IF v_payment.reversal_kind IS NOT NULL THEN
    RAISE EXCEPTION 'already_reversed: este pagamento já foi estornado (%)', v_payment.reversal_kind;
  END IF;

  IF v_payment.status <> 'paid' THEN
    RAISE EXCEPTION 'payment_not_paid: só parcelas pagas podem ser estornadas (status atual: %)', v_payment.status;
  END IF;

  SELECT * INTO v_tx FROM public.transactions WHERE id = v_payment.transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transaction_not_found';
  END IF;

  IF p_kind = 'supplier_credit' THEN
    IF v_tx.supplier_id IS NULL THEN
      RAISE EXCEPTION 'no_supplier: a transação não tem fornecedor definido — não é possível criar crédito';
    END IF;

    v_credit_amount := coalesce(p_amount, v_payment.amount);
    IF v_credit_amount <= 0 OR v_credit_amount > v_payment.amount + 0.01 THEN
      RAISE EXCEPTION 'invalid_amount: valor do crédito deve estar entre 0 e % (valor do pagamento)', v_payment.amount;
    END IF;

    INSERT INTO public.supplier_credits (
      supplier_id, origin_event_id, amount, used_amount, reason, valid_until, status, created_by, company_id
    )
    VALUES (
      v_tx.supplier_id,
      v_tx.event_id,
      v_credit_amount,
      0,
      'Estorno: ' || p_reason || ' (TX ref ' || v_tx.id::text || ')',
      p_valid_until,
      'active',
      coalesce((SELECT email FROM auth.users WHERE id = v_uid), 'sistema'),
      v_payment.company_id
    )
    RETURNING id INTO v_credit_id;

    UPDATE public.transaction_payments
       SET reversal_kind = 'supplier_credit',
           reversal_reason = p_reason,
           reversed_at = now(),
           reversed_by = v_uid,
           supplier_credit_id = v_credit_id,
           updated_at = now()
     WHERE id = p_payment_id;

  ELSE
    UPDATE public.transaction_payments
       SET status = 'reversed',
           reversal_kind = 'cash_refund',
           reversal_reason = p_reason,
           reversed_at = now(),
           reversed_by = v_uid,
           updated_at = now()
     WHERE id = p_payment_id;

    IF NOT public.tx_has_installment_schedule(v_tx.id) THEN
      DECLARE
        v_paid_sum numeric;
        v_max_date date;
        v_gross numeric := v_tx.amount * (1 + coalesce(v_tx.iva_rate, 0) / 100.0);
      BEGIN
        SELECT coalesce(SUM(amount),0), MAX(payment_date) INTO v_paid_sum, v_max_date
          FROM public.transaction_payments
         WHERE transaction_id = v_tx.id AND status = 'paid';

        IF v_paid_sum <= 0.01 THEN
          UPDATE public.transactions
             SET paid_amount = 0,
                 status = CASE WHEN status IN ('paid','partially_paid') THEN 'approved' ELSE status END,
                 payment_date = NULL,
                 updated_at = now()
           WHERE id = v_tx.id;
        ELSIF v_paid_sum >= v_gross - 0.01 THEN
          UPDATE public.transactions
             SET paid_amount = v_paid_sum, status = 'paid', payment_date = v_max_date, updated_at = now()
           WHERE id = v_tx.id;
        ELSE
          UPDATE public.transactions
             SET paid_amount = v_paid_sum, status = 'partially_paid', payment_date = NULL, updated_at = now()
           WHERE id = v_tx.id;
        END IF;
      END;
    END IF;

    DELETE FROM public.payment_list_items
     WHERE transaction_id = v_tx.id
       AND payment_list_id IN (
         SELECT id FROM public.payment_lists
          WHERE status IN ('draft','pending_approval')
       );
  END IF;

  BEGIN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, new_data, metadata)
    VALUES (
      'transaction_payment',
      p_payment_id::text,
      'reverse_payment_' || p_kind,
      coalesce((SELECT email FROM auth.users WHERE id = v_uid), 'sistema'),
      jsonb_build_object('status', v_payment.status, 'amount', v_payment.amount, 'account_id', v_payment.account_id),
      jsonb_build_object('reversal_kind', p_kind, 'reason', p_reason, 'supplier_credit_id', v_credit_id, 'credit_amount', v_credit_amount),
      jsonb_build_object('transaction_id', v_tx.id, 'event_id', v_tx.event_id)
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'kind', p_kind,
    'payment_id', p_payment_id,
    'transaction_id', v_tx.id,
    'supplier_credit_id', v_credit_id,
    'credit_amount', v_credit_amount
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._apply_transaction_offset(p_offset_id uuid, p_origin_payment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  o record; op record; src record; oth record;
  v_other uuid; v_open numeric; v_amt numeric; v_new uuid;
BEGIN
  SELECT * INTO o FROM public.transaction_offsets WHERE id = p_offset_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO op FROM public.transaction_payments WHERE id = p_origin_payment_id;
  IF NOT FOUND OR op.payment_method = 'compensation' OR op.status <> 'paid' OR op.reversed_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  IF op.transaction_id = o.receivable_transaction_id THEN
    v_other := o.payable_transaction_id;
  ELSIF op.transaction_id = o.payable_transaction_id THEN
    v_other := o.receivable_transaction_id;
  ELSE
    RETURN NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM public.transaction_payments x
              WHERE x.offset_id = o.id AND x.transaction_id = v_other
                AND x.status = 'paid' AND x.reversed_at IS NULL) THEN
    RETURN NULL;
  END IF;

  SELECT * INTO src FROM public.transactions WHERE id = op.transaction_id;
  SELECT * INTO oth FROM public.transactions WHERE id = v_other;
  SELECT round(oth.amount * (1 + COALESCE(oth.iva_rate, 0) / 100.0), 2)
         - COALESCE((SELECT SUM(x.amount) FROM public.transaction_payments x
                      WHERE x.transaction_id = v_other AND x.status IN ('planned','paid')), 0)
    INTO v_open;
  v_amt := round(LEAST(o.amount, v_open), 2);
  IF v_amt <= 0.01 THEN RETURN NULL; END IF;

  INSERT INTO public.transaction_payments (
    transaction_id, amount, payment_date, account_id, payment_method,
    payment_reference, notes, created_by, company_id, status, offset_id,
    closes_transaction, currency
  ) VALUES (
    v_other, v_amt, op.payment_date, NULL, 'compensation',
    left('Compensação com ' || COALESCE(src.description, src.id::text), 250),
    'Gerado pela ligação de compensação ' || o.id::text,
    op.created_by, oth.company_id, 'paid', o.id,
    (COALESCE(oth.currency, 'EUR') <> 'EUR' AND v_amt >= v_open - 0.05),
    'EUR'
  ) RETURNING id INTO v_new;

  -- Chamada a partir de um trigger: o sync_paid_amount_from_payments do INSERT
  -- acima corre com depth > 1 e sai sem derivar — deriva-se aqui com a MESMA
  -- função (contexto do dono do trigger). Chamada a partir da RPC (depth 0):
  -- o sync corre normalmente.
  IF pg_trigger_depth() > 0 THEN
    PERFORM public._derive_paid_amount(v_other);
  END IF;
  RETURN v_new;
END;
$function$

CREATE OR REPLACE FUNCTION public.renegotiate_transaction_installments(p_transaction_id uuid, p_installments jsonb, p_changed_by text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- Renegocia uma despesa de pagamento único num grupo estrutural de N parcelas.
--
-- p_installments: array ORDENADO de { "due_date": "YYYY-MM-DD", "amount": <BASE, sem IVA> }.
-- O cliente converte bruto->base (computeInstallmentNets) ANTES de chamar.
DECLARE
  v_uid uuid := auth.uid();
  v_tx public.transactions%ROWTYPE;
  v_n int;
  v_sum numeric := 0;
  v_group_id uuid;
  v_base_desc text;
  v_item jsonb;
  v_i int;
  v_amount numeric;
  v_due date;
  v_first_amount numeric;
  v_first_due date;
  v_old_amount numeric;
  v_old_due date;
  v_new_id uuid;
  v_event_status text;
BEGIN
  IF NOT (
    public.has_role(v_uid, 'admin'::app_role)
    OR public.has_role(v_uid, 'manager'::app_role)
    OR public.has_permission(v_uid, 'manage_transactions')
  ) THEN
    RAISE EXCEPTION 'permission_denied: sem permissão para renegociar em parcelas';
  END IF;

  SELECT * INTO v_tx FROM public.transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transaction_not_found: %', p_transaction_id;
  END IF;

  IF v_tx.type <> 'expense' THEN
    RAISE EXCEPTION 'not_expense: apenas despesas podem ser renegociadas em parcelas';
  END IF;

  IF coalesce(v_tx.paid_amount, 0) > 0 THEN
    RAISE EXCEPTION 'already_paid: a transação já tem valor pago (%)', v_tx.paid_amount;
  END IF;

  IF EXISTS (SELECT 1 FROM public.transaction_payments WHERE transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'has_payments: a transação já tem pagamentos registados';
  END IF;

  IF v_tx.installment_group_id IS NOT NULL THEN
    RAISE EXCEPTION 'already_installment_group: a transação já pertence a um grupo de parcelas';
  END IF;

  IF v_tx.split_percentage IS NOT NULL THEN
    RAISE EXCEPTION 'is_split: transações de rateio não podem ser renegociadas em parcelas';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.transactions
     WHERE parent_transaction_id = p_transaction_id
       AND split_percentage IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'is_split_parent: transações rateadas entre eventos não podem ser renegociadas em parcelas; ajuste o rateio primeiro';
  END IF;

  IF coalesce(v_tx.is_reimbursement, false) THEN
    RAISE EXCEPTION 'is_reimbursement: notas de reembolso não podem ser renegociadas em parcelas';
  END IF;

  IF coalesce(v_tx.is_transitory, false) THEN
    RAISE EXCEPTION 'is_transitory: transações transitórias não podem ser renegociadas em parcelas';
  END IF;

  IF EXISTS (SELECT 1 FROM public.partner_paid_expenses WHERE transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'is_partner_paid: despesas pagas por sócio não podem ser renegociadas em parcelas';
  END IF;

  IF EXISTS (SELECT 1 FROM public.partner_advance_expenses WHERE transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'is_partner_extra: extras de sócio não podem ser renegociados em parcelas';
  END IF;

  IF v_tx.event_id IS NOT NULL THEN
    SELECT status INTO v_event_status FROM public.events WHERE id = v_tx.event_id;
    IF v_event_status = 'completed' THEN
      RAISE EXCEPTION 'event_completed: o evento associado está fechado';
    END IF;
  END IF;

  IF p_installments IS NULL OR jsonb_typeof(p_installments) <> 'array' THEN
    RAISE EXCEPTION 'invalid_installments: lista de parcelas inválida';
  END IF;

  v_n := jsonb_array_length(p_installments);
  IF v_n < 2 THEN
    RAISE EXCEPTION 'too_few_installments: são necessárias pelo menos 2 parcelas (recebidas %)', v_n;
  END IF;

  FOR v_i IN 0..v_n - 1 LOOP
    v_item := p_installments -> v_i;
    IF v_item ->> 'due_date' IS NULL OR trim(v_item ->> 'due_date') = '' THEN
      RAISE EXCEPTION 'invalid_due_date: parcela % sem data de vencimento', v_i + 1;
    END IF;
    v_amount := (v_item ->> 'amount')::numeric;
    IF v_amount IS NULL OR v_amount <= 0 THEN
      RAISE EXCEPTION 'invalid_amount: parcela % com valor inválido', v_i + 1;
    END IF;
    v_sum := v_sum + v_amount;
  END LOOP;

  IF abs(v_sum - v_tx.amount) > 0.01 THEN
    RAISE EXCEPTION 'installments_sum_mismatch: soma das parcelas % difere do valor da transação %', v_sum, v_tx.amount;
  END IF;

  v_group_id := gen_random_uuid();
  v_base_desc := trim(regexp_replace(coalesce(v_tx.description, ''), '\(\s*\d+\s*/\s*\d+\s*\)\s*$', ''));
  v_old_amount := v_tx.amount;
  v_old_due := v_tx.due_date;
  v_first_amount := ((p_installments -> 0) ->> 'amount')::numeric;
  v_first_due := ((p_installments -> 0) ->> 'due_date')::date;

  UPDATE public.transactions
     SET description = v_base_desc || ' (1/' || v_n || ')',
         amount = v_first_amount,
         due_date = v_first_due,
         installment_group_id = v_group_id,
         installment_number = 1,
         installment_total = v_n,
         original_amount = CASE
           WHEN coalesce(v_tx.currency, 'EUR') <> 'EUR' AND v_tx.original_amount IS NOT NULL AND coalesce(v_old_amount, 0) <> 0
             THEN round(v_tx.original_amount * v_first_amount / v_old_amount, 2)
           ELSE v_tx.original_amount
         END,
         updated_at = now()
   WHERE id = p_transaction_id;

  INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
  VALUES
    (p_transaction_id, p_changed_by, 'Valor (renegociação em parcelas)', round(v_old_amount, 2)::text, round(v_first_amount, 2)::text),
    (p_transaction_id, p_changed_by, 'Data Vencimento (renegociação em parcelas)', coalesce(v_old_due::text, ''), v_first_due::text);

  FOR v_i IN 1..v_n - 1 LOOP
    v_item := p_installments -> v_i;
    v_amount := (v_item ->> 'amount')::numeric;
    v_due := (v_item ->> 'due_date')::date;

    INSERT INTO public.transactions (
      description, type, amount, iva_rate, event_id, category_id, supplier_id, account_id,
      specification, date, due_date, status, paid_amount, payment_date,
      is_reimbursement, is_transitory, exclude_from_result,
      invoice_ref, invoice_group_id, payment_method, payment_entity, payment_reference,
      operation_key,
      ordering_partner_id, paying_partner_id,
      currency, fx_rate, fx_rate_source, original_amount,
      parent_transaction_id, installment_group_id, installment_number, installment_total,
      split_percentage, split_amount, company_id
    ) VALUES (
      v_base_desc || ' (' || (v_i + 1) || '/' || v_n || ')',
      v_tx.type, v_amount, v_tx.iva_rate, v_tx.event_id, v_tx.category_id, v_tx.supplier_id, v_tx.account_id,
      v_tx.specification, v_tx.date, v_due, v_tx.status, 0, NULL,
      false, false, coalesce(v_tx.exclude_from_result, false),
      v_tx.invoice_ref, v_tx.invoice_group_id, coalesce(v_tx.payment_method, 'transfer'), v_tx.payment_entity, v_tx.payment_reference,
      v_tx.operation_key,
      v_tx.ordering_partner_id, v_tx.paying_partner_id,
      coalesce(v_tx.currency, 'EUR'), v_tx.fx_rate, v_tx.fx_rate_source,
      CASE
        WHEN coalesce(v_tx.currency, 'EUR') <> 'EUR' AND v_tx.original_amount IS NOT NULL AND coalesce(v_old_amount, 0) <> 0
          THEN round(v_tx.original_amount * v_amount / v_old_amount, 2)
        ELSE NULL
      END,
      p_transaction_id, v_group_id, v_i + 1, v_n,
      NULL, NULL, v_tx.company_id
    )
    RETURNING id INTO v_new_id;

    INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
    VALUES (
      v_new_id, p_changed_by, 'Criação (renegociação em parcelas)', NULL,
      v_base_desc || ' (' || (v_i + 1) || '/' || v_n || ') — ' || round(v_amount, 2)::text || ' € (base) — venc. ' || v_due::text
    );
  END LOOP;

  RETURN v_group_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.card_load_on_out_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_load  public.card_session_loads%ROWTYPE;
  v_sess  public.card_sessions%ROWTYPE;
  v_src_name TEXT;
  v_card_name TEXT;
  v_cat_id UUID;
  v_in_id UUID;
BEGIN
  IF NEW.status <> 'paid' OR OLD.status = 'paid' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_load
  FROM public.card_session_loads
  WHERE out_transaction_id = NEW.id
    AND in_transaction_id IS NULL
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_sess FROM public.card_sessions WHERE id = v_load.session_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  SELECT name INTO v_src_name  FROM public.financial_accounts WHERE id = v_load.source_account_id;
  SELECT name INTO v_card_name FROM public.financial_accounts WHERE id = v_sess.card_account_id;
  SELECT id   INTO v_cat_id    FROM public.account_categories  WHERE code = '10.3' LIMIT 1;

  INSERT INTO public.transactions (
    company_id, type, description, amount, iva_rate, date,
    status, paid_amount, payment_date,
    is_transitory, transitory_reason, exclude_from_result, category_id, account_id
  ) VALUES (
    NEW.company_id, 'income',
    'Carga de ' || COALESCE(v_src_name,'origem') || ' (' || COALESCE(v_src_name,'origem') || ' → ' || COALESCE(v_card_name,'cartão') || ')',
    v_load.amount, 0, v_load.load_date,
    'paid', v_load.amount, COALESCE(NEW.payment_date, v_load.load_date),
    TRUE, 'carga_cartao', TRUE, v_cat_id, v_sess.card_account_id
  ) RETURNING id INTO v_in_id;

  UPDATE public.card_session_loads
     SET in_transaction_id = v_in_id
   WHERE id = v_load.id;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.materialize_paid_amount_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sum numeric; v_diff numeric; v_method text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.paid_amount IS NOT DISTINCT FROM OLD.paid_amount THEN RETURN NULL; END IF;
  IF TG_OP = 'INSERT' AND COALESCE(NEW.paid_amount, 0) <= 0.01 THEN RETURN NULL; END IF;
  IF public._paid_guard_is_exempt(NEW) THEN RETURN NULL; END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_sum FROM public.transaction_payments
   WHERE transaction_id = NEW.id AND status = 'paid';
  v_diff := round(COALESCE(NEW.paid_amount, 0) - v_sum, 2);
  IF abs(v_diff) <= 0.01 THEN RETURN NULL; END IF;

  IF v_diff < 0 THEN
    UPDATE public.transaction_payments
       SET status = 'reversed', reversed_at = now(),
           reversal_reason = 'reajuste automático do valor pago (D-ERP157)'
     WHERE transaction_id = NEW.id AND status = 'paid' AND created_by = 'base D-ERP157';
    SELECT COALESCE(SUM(amount), 0) INTO v_sum FROM public.transaction_payments
     WHERE transaction_id = NEW.id AND status = 'paid';
    v_diff := round(COALESCE(NEW.paid_amount, 0) - v_sum, 2);
  END IF;

  IF v_diff > 0.01 THEN
    v_method := CASE WHEN NEW.account_id IS NULL THEN 'compensation'
                     WHEN NEW.payment_method IN ('transfer','service_payment','direct_debit','state_payment') THEN NEW.payment_method
                     ELSE 'transfer' END;
    INSERT INTO public.transaction_payments
      (transaction_id, amount, payment_date, account_id, payment_method, status,
       closes_transaction, company_id, created_by, notes)
    VALUES
      (NEW.id, v_diff, COALESCE(NEW.payment_date, NEW.date, current_date),
       CASE WHEN v_method = 'compensation' THEN NULL ELSE NEW.account_id END,
       v_method, 'paid', NEW.status = 'paid', NEW.company_id, 'base D-ERP157',
       'Criado pela base: transação gravada com valor pago sem linha de pagamento ('
         || COALESCE(auth.jwt() ->> 'email', current_user) || ')');
  END IF;

  PERFORM public._derive_paid_amount(NEW.id);
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.launch_from_bank_lines(p_items jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb;
  v_tx jsonb;
  v_line_ids uuid[];
  v_all_ids uuid[] := '{}';
  v_company uuid;
  v_current uuid;
  v_n_lines int;
  v_n_found int;
  v_bad uuid;
  v_cols text[];
  v_key text;
  v_sql text;
  v_tx_id uuid;
  v_out uuid[] := '{}';
  v_matched_by text;
  v_note text;
  v_rows int;
  v_was_paid boolean;
  v_pay_amount numeric;
  v_gross numeric;
  v_pay_date date;
  v_pay_acc uuid;
  v_pay_method text;
  v_currency text;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Nada a lançar: p_items tem de ser um array com pelo menos um item.';
  end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item -> 'transaction') <> 'object' then
      raise exception 'Item sem objecto "transaction".';
    end if;
    if v_item ? 'line_ids' and jsonb_typeof(v_item -> 'line_ids') = 'array' then
      select v_all_ids || coalesce(array_agg((x)::uuid), '{}')
        into v_all_ids
        from jsonb_array_elements_text(v_item -> 'line_ids') x;
    end if;
  end loop;

  if array_length(v_all_ids, 1) is null then
    raise exception 'Nenhuma linha do banco indicada — o lançamento tem de ficar ligado ao extrato.';
  end if;

  v_n_lines := array_length(v_all_ids, 1);

  select count(*), count(distinct l.company_id), (array_agg(distinct l.company_id))[1]
    into v_n_found, v_rows, v_company
    from public.bank_statement_lines l
   where l.id = any(v_all_ids);

  if v_n_found <> v_n_lines then
    raise exception 'Linha(s) do banco inexistente(s) ou sem acesso: pedidas %, encontradas %.', v_n_lines, v_n_found;
  end if;
  if v_rows <> 1 or v_company is null then
    raise exception 'As linhas do banco não pertencem todas à mesma empresa.';
  end if;

  v_current := public.current_company_id();
  if v_current is null or v_current <> v_company then
    raise exception 'As linhas do banco pertencem a outra empresa (%) — empresa activa %.', v_company, v_current;
  end if;

  select l.id into v_bad
    from public.bank_statement_lines l
   where l.id = any(v_all_ids)
     and (l.status <> 'unmatched'
          or l.matched_transaction_id is not null
          or l.created_transaction_id is not null)
   limit 1;

  if v_bad is not null then
    raise exception 'Linha do banco já está conciliada: %', v_bad;
  end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_tx := v_item -> 'transaction';

    -- D-ERP157: nasce 'approved' sem valor pago; o pagamento nasce em transaction_payments.
    v_was_paid := (v_tx ->> 'status') = 'paid'
                  or coalesce(nullif(v_tx ->> 'paid_amount', '')::numeric, 0) > 0.01;
    v_pay_amount := nullif(coalesce(nullif(v_tx ->> 'paid_amount', '')::numeric, 0), 0);
    v_pay_method := nullif(v_tx ->> 'payment_method', '');
    v_tx := v_tx - 'paid_amount' - 'payment_date';
    if (v_tx ->> 'status') = 'paid' then
      v_tx := jsonb_set(v_tx, '{status}', '"approved"');
    end if;

    v_cols := '{}';
    for v_key in select k from jsonb_object_keys(v_tx) k loop
      if v_key in ('id', 'company_id', 'created_at', 'updated_at') then
        continue;
      end if;
      if not exists (
        select 1 from information_schema.columns c
         where c.table_schema = 'public' and c.table_name = 'transactions'
           and c.column_name = v_key
      ) then
        raise exception 'Coluna inexistente em transactions: %', v_key;
      end if;
      v_cols := v_cols || v_key;
    end loop;

    if array_length(v_cols, 1) is null then
      raise exception 'Item sem colunas válidas para transactions.';
    end if;

    v_sql := format(
      'insert into public.transactions (company_id, %s) select $2, %s from jsonb_populate_record(null::public.transactions, $1) r returning id',
      (select string_agg(quote_ident(c), ', ') from unnest(v_cols) c),
      (select string_agg('r.' || quote_ident(c), ', ') from unnest(v_cols) c)
    );
    execute v_sql into v_tx_id using v_tx, v_company;

    if v_tx_id is null then
      raise exception 'A transação não foi criada.';
    end if;
    v_out := v_out || v_tx_id;

    v_line_ids := '{}';
    if v_item ? 'line_ids' and jsonb_typeof(v_item -> 'line_ids') = 'array' then
      select coalesce(array_agg((x)::uuid), '{}') into v_line_ids
        from jsonb_array_elements_text(v_item -> 'line_ids') x;
    end if;

    if array_length(v_line_ids, 1) is not null then
      v_matched_by := coalesce(v_item ->> 'matched_by', 'created:sistema');
      v_note := nullif(v_item ->> 'note', '');

      update public.bank_statement_lines
         set status = 'matched',
             created_transaction_id = v_tx_id,
             matched_transaction_id = v_tx_id,
             matched_by = v_matched_by,
             matched_at = now(),
             note = v_note
       where id = any(v_line_ids);

      get diagnostics v_rows = row_count;
      if v_rows <> array_length(v_line_ids, 1) then
        raise exception 'Só % de % linhas do banco ficaram ligadas — nada fica gravado.', v_rows, array_length(v_line_ids, 1);
      end if;
    end if;

    if v_was_paid then
      select round((t.amount * (1 + coalesce(t.iva_rate, 0) / 100.0))::numeric, 2),
             coalesce(t.currency, 'EUR'), t.account_id, t.date
        into v_gross, v_currency, v_pay_acc, v_pay_date
        from public.transactions t where t.id = v_tx_id;

      if array_length(v_line_ids, 1) is not null then
        select max(coalesce(l.value_date, l.booking_date)),
               (array_agg(l.financial_account_id))[1]
          into v_pay_date, v_pay_acc
          from public.bank_statement_lines l
         where l.id = any(v_line_ids);
      end if;

      insert into public.transaction_payments
        (transaction_id, amount, payment_date, account_id, payment_method,
         status, closes_transaction, company_id, created_by, notes)
      values
        (v_tx_id, coalesce(v_pay_amount, v_gross), coalesce(v_pay_date, current_date),
         v_pay_acc,
         case when v_pay_acc is null then 'compensation'
              when v_pay_method in ('transfer','service_payment','direct_debit','state_payment') then v_pay_method
              else 'transfer' end,
         'paid', v_currency <> 'EUR', v_company,
         coalesce(auth.jwt() ->> 'email', 'sistema'),
         'Lançado a partir da linha do banco');
    end if;
  end loop;

  return v_out;
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_transaction(p_tx_id uuid, p_kind text, p_reason text, p_valid_until date, p_release_for_repayment boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx RECORD;
  v_uid uuid := auth.uid();
  v_credit_id uuid;
  v_paid_amount numeric;
  v_account_name text;
  v_removed_from_lists jsonb := '[]'::jsonb;
  v_list RECORD;
BEGIN
  IF NOT (public.has_role(v_uid, 'admin'::app_role) OR public.has_role(v_uid, 'platform_admin'::app_role)) THEN
    RAISE EXCEPTION 'Apenas administradores podem estornar transações';
  END IF;

  IF p_kind NOT IN ('cash_refund','supplier_credit') THEN
    RAISE EXCEPTION 'Tipo de estorno inválido: %', p_kind;
  END IF;

  IF coalesce(trim(p_reason),'') = '' THEN
    RAISE EXCEPTION 'Motivo é obrigatório';
  END IF;

  SELECT * INTO v_tx FROM public.transactions WHERE id = p_tx_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transação não encontrada'; END IF;
  IF v_tx.status = 'reversed' THEN RAISE EXCEPTION 'Transação já está estornada'; END IF;
  IF coalesce(v_tx.paid_amount,0) <= 0 AND v_tx.status <> 'paid' THEN
    RAISE EXCEPTION 'Só transações com pagamento registado podem ser estornadas';
  END IF;

  v_paid_amount := coalesce(v_tx.paid_amount, 0);

  SELECT name INTO v_account_name FROM public.financial_accounts WHERE id = v_tx.account_id;

  IF p_kind = 'supplier_credit' THEN
    IF v_tx.supplier_id IS NULL THEN
      RAISE EXCEPTION 'Transação não tem fornecedor — não é possível criar crédito';
    END IF;

    INSERT INTO public.supplier_credits (
      supplier_id, origin_event_id, amount, reason, valid_until,
      document_ref, status, created_by, company_id
    ) VALUES (
      v_tx.supplier_id, v_tx.event_id, v_paid_amount,
      'Estorno tx ' || v_tx.id::text || ' — ' || p_reason,
      p_valid_until, 'reverse_tx:' || v_tx.id::text, 'active',
      coalesce(v_uid::text, 'system'), v_tx.company_id
    ) RETURNING id INTO v_credit_id;

    UPDATE public.transaction_payments
       SET reversal_kind = 'supplier_credit', reversal_reason = p_reason,
           reversed_at = now(), reversed_by = v_uid, supplier_credit_id = v_credit_id
     WHERE transaction_id = p_tx_id AND status = 'paid' AND reversal_kind IS NULL;
  ELSE
    UPDATE public.transaction_payments
       SET status = 'reversed', reversal_kind = 'cash_refund',
           reversal_reason = p_reason, reversed_at = now(), reversed_by = v_uid
     WHERE transaction_id = p_tx_id AND status = 'paid';
  END IF;

  DELETE FROM public.payment_list_items pli
   USING public.payment_lists pl
   WHERE pli.transaction_id = p_tx_id
     AND pli.payment_list_id = pl.id
     AND pl.status IN ('draft','pending_approval');

  IF p_release_for_repayment THEN
    FOR v_list IN
      SELECT pl.id AS list_id, pl.title AS list_name, pl.status AS list_status, pli.id AS pli_id
        FROM public.payment_list_items pli
        JOIN public.payment_lists pl ON pl.id = pli.payment_list_id
       WHERE pli.transaction_id = p_tx_id
         AND pl.status IN ('partially_approved','approved','paid')
    LOOP
      DELETE FROM public.payment_list_items WHERE id = v_list.pli_id;
      v_removed_from_lists := v_removed_from_lists || jsonb_build_object(
        'list_id', v_list.list_id, 'list_name', v_list.list_name, 'list_status', v_list.list_status
      );
    END LOOP;
  ELSE
    FOR v_list IN
      SELECT pl.id AS list_id, pl.title AS list_name, pl.status AS list_status
        FROM public.payment_list_items pli
        JOIN public.payment_lists pl ON pl.id = pli.payment_list_id
       WHERE pli.transaction_id = p_tx_id
         AND pl.status IN ('partially_approved','approved','paid')
    LOOP
      INSERT INTO public.transaction_audit_log (
        transaction_id, changed_by, field_name, old_value, new_value, company_id
      ) VALUES (
        p_tx_id, coalesce(v_uid::text, 'system'),
        'Estorno — lista mantida',
        v_list.list_name || ' (' || v_list.list_status || ')',
        'Transação estornada mas mantida na lista (modo conservador). Para libertar, refaça o estorno com "libertar para nova liquidação".',
        v_tx.company_id
      );
    END LOOP;
  END IF;

  IF p_release_for_repayment THEN
    UPDATE public.transactions
       SET status = 'pending',
           paid_amount = 0,
           payment_date = NULL,
           reversal_kind = p_kind,
           reversal_reason = p_reason,
           reversed_at = now(),
           reversed_by = v_uid,
           supplier_credit_id = CASE WHEN p_kind='supplier_credit' THEN v_credit_id ELSE supplier_credit_id END,
           updated_at = now()
     WHERE id = p_tx_id;
  ELSE
    UPDATE public.transactions
       SET status = 'reversed',
           paid_amount = CASE WHEN p_kind='cash_refund' THEN 0 ELSE paid_amount END,
           payment_date = CASE WHEN p_kind='cash_refund' THEN NULL ELSE payment_date END,
           reversal_kind = p_kind,
           reversal_reason = p_reason,
           reversed_at = now(),
           reversed_by = v_uid,
           supplier_credit_id = CASE WHEN p_kind='supplier_credit' THEN v_credit_id ELSE supplier_credit_id END,
           updated_at = now()
     WHERE id = p_tx_id;
  END IF;

  INSERT INTO public.transaction_audit_log (
    transaction_id, changed_by, field_name, old_value, new_value, company_id
  ) VALUES (
    p_tx_id,
    coalesce(v_uid::text, 'system'),
    'Estorno',
    'paid',
    CASE WHEN p_kind = 'cash_refund'
         THEN 'Devolução em dinheiro — ' || to_char(v_paid_amount,'FM999G999G990D00') || ' € repostos' ||
              coalesce(' em ' || v_account_name, '') || ' — ' || p_reason
         ELSE 'Crédito do fornecedor — ' || to_char(v_paid_amount,'FM999G999G990D00') || ' € — ' || p_reason
    END
      || CASE WHEN p_release_for_repayment
              THEN ' · Libertada para nova liquidação (status → A pagar)'
              ELSE ' · Estornada (status → Estornada)'
         END,
    v_tx.company_id
  );

  INSERT INTO public.system_audit_log (
    entity_type, entity_id, action, changed_by, old_data, new_data, metadata, company_id
  ) VALUES (
    'transaction', p_tx_id::text, 'reverse_transaction_' || p_kind,
    coalesce(v_uid::text, 'system'), to_jsonb(v_tx),
    jsonb_build_object(
      'status', CASE WHEN p_release_for_repayment THEN 'pending' ELSE 'reversed' END,
      'reversal_kind', p_kind,
      'reversal_reason', p_reason,
      'supplier_credit_id', v_credit_id,
      'released_for_repayment', p_release_for_repayment,
      'removed_from_lists', v_removed_from_lists
    ),
    jsonb_build_object(
      'reason', p_reason,
      'amount', v_paid_amount,
      'supplier_credit_id', v_credit_id,
      'valid_until', p_valid_until,
      'released_for_repayment', p_release_for_repayment
    ),
    v_tx.company_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'transaction_id', p_tx_id,
    'kind', p_kind,
    'supplier_credit_id', v_credit_id,
    'released_for_repayment', p_release_for_repayment,
    'new_status', CASE WHEN p_release_for_repayment THEN 'pending' ELSE 'reversed' END,
    'removed_from_lists', v_removed_from_lists
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.data_entry_assistant_execute_333(p_mode text, p_authorization uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid(); v_company uuid; a public.data_entry_assistant_authorizations_333; v public.data_entry_assistant_review_versions_333;
  cur_version integer; act jsonb; e jsonb; c jsonb; ex public.data_entry_assistant_executions_333; res jsonb; dep text; x jsonb;
  v_office uuid; v_event uuid; v_st uuid; v_n int; v_sum numeric; s record; t record; v_amount numeric; v_date date;
  v_gross numeric; v_set uuid; v_email text; v_key text; v_legs int; v_bad int; v_paid int; v_div int; v_total bigint; v_sdate date;
  v_exp jsonb; v_act jsonb; v_to uuid; v_ok boolean;
BEGIN
  IF p_mode = 'probe' THEN
    RETURN jsonb_build_object('schema', '333-12f', 'enabled', coalesce((SELECT enabled FROM public.data_entry_assistant_executor_settings_333 WHERE singleton), false));
  END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  v_company := public.current_company_id();
  IF v_company IS NULL
     OR NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_uid AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until <= now()))
     OR NOT EXISTS (SELECT 1 FROM public.companies WHERE id = v_company AND status = 'active')
     OR coalesce(public._effective_permissions_for(v_uid, v_company, '{}'::text[])->>'role', '') NOT IN ('admin', 'manager')
  THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;

  IF p_mode = 'status' THEN
    SELECT * INTO a FROM public.data_entry_assistant_authorizations_333 WHERE id = p_authorization;
    IF NOT FOUND OR a.owner_id IS DISTINCT FROM v_uid OR a.company_id IS DISTINCT FROM v_company THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    RETURN jsonb_build_object('authorization_id', a.id, 'action_ids', to_jsonb(a.action_ids), 'executions',
      coalesce((SELECT jsonb_agg(jsonb_build_object('action_id', y.action_id, 'status', y.status, 'result', y.result, 'at', y.created_at) ORDER BY y.created_at)
        FROM public.data_entry_assistant_executions_333 y WHERE y.authorization_id = a.id), '[]'::jsonb));
  END IF;
  IF p_mode <> 'execute' THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '22023'; END IF;
  IF NOT coalesce((SELECT enabled FROM public.data_entry_assistant_executor_settings_333 WHERE singleton), false) THEN RAISE EXCEPTION '#333: executor_closed' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.data_entry_assistant_scope_333 WHERE owner_id = v_uid AND company_id = v_company AND expires_at > now())
  THEN RAISE EXCEPTION '#333: scope_closed' USING ERRCODE = '42501'; END IF;

  SELECT * INTO a FROM public.data_entry_assistant_authorizations_333 WHERE id = p_authorization FOR UPDATE;
  IF NOT FOUND OR a.owner_id IS DISTINCT FROM v_uid OR a.company_id IS DISTINCT FROM v_company THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  SELECT * INTO ex FROM public.data_entry_assistant_executions_333 WHERE authorization_id = a.id AND action_id = p_action;
  IF FOUND THEN RETURN jsonb_build_object('action_id', p_action, 'status', ex.status, 'replayed', true, 'result', ex.result); END IF;
  IF p_action IS NULL OR NOT (p_action = ANY (a.action_ids)) THEN RAISE EXCEPTION '#333: action_not_authorized' USING ERRCODE = 'P0001'; END IF;

  -- 12h: FOR SHARE conflita com o FOR UPDATE do 'save' (nova versão): o executor espera e vê a versão nova (stale_version),
  -- em vez de executar uma versão revogada em simultâneo (bug confirmado com 2 ligações, grupo 24f).
  SELECT version INTO cur_version FROM public.data_entry_assistant_reviews_333 WHERE id = a.review_id FOR SHARE;
  IF cur_version IS DISTINCT FROM a.version THEN RAISE EXCEPTION '#333: stale_version' USING ERRCODE = '40001'; END IF;
  SELECT * INTO v FROM public.data_entry_assistant_review_versions_333 WHERE review_id = a.review_id AND version = a.version;
  IF NOT FOUND OR v.effects_hash IS DISTINCT FROM a.effects_hash
     OR encode(sha256(convert_to(public._de333_canon(jsonb_build_object('effects', v.proposal->'effects', 'actions', v.proposal->'actions')), 'UTF8')), 'hex') IS DISTINCT FROM a.effects_hash
  THEN RAISE EXCEPTION '#333: hash_mismatch' USING ERRCODE = '22023'; END IF;
  -- Contrato de ações fixo (server-owned): ids, tipos e dependências; a5 depende de a3 ou, com fecho já confirmado, de nada.
  IF jsonb_typeof(v.proposal->'actions') IS DISTINCT FROM 'array'
     OR (SELECT count(DISTINCT y->>'id') FROM jsonb_array_elements(v.proposal->'actions') y) IS DISTINCT FROM jsonb_array_length(v.proposal->'actions')::bigint
  THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
  FOR x IN SELECT y FROM jsonb_array_elements(v.proposal->'actions') y LOOP
    IF ((x->>'id', x->>'kind', x->'depends_on') IN (('a1','create_statement','[]'::jsonb), ('a2','confirm_statement','["a1"]'::jsonb),
        ('a4','verify_deductions','["a2"]'::jsonb), ('a3','save_settlement','["a4"]'::jsonb), ('a5','register_liquidation','["a3"]'::jsonb), ('a5','register_liquidation','[]'::jsonb))) IS NOT TRUE
    THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
  END LOOP;
  e := v.proposal->'effects';
  IF e->>'company' IS DISTINCT FROM v_company::text OR v.proposal->>'company_id' IS DISTINCT FROM v_company::text OR coalesce((e->>'human_reviewed')::boolean, false) IS NOT TRUE
  THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  SELECT y INTO act FROM jsonb_array_elements(v.proposal->'actions') y WHERE y->>'id' = p_action;
  IF act IS NULL OR act->'blocked_reason' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
  FOR dep IN SELECT jsonb_array_elements_text(act->'depends_on') LOOP
    IF NOT (dep = ANY (a.action_ids)) OR NOT EXISTS (SELECT 1 FROM public.data_entry_assistant_executions_333 WHERE authorization_id = a.id AND action_id = dep)
    THEN RAISE EXCEPTION '#333: dependency_pending' USING ERRCODE = 'P0001'; END IF;
  END LOOP;
  v_event := public._de333_req(e, 'event')::uuid;
  v_office := public._de333_req(e, 'office')::uuid;

  IF p_action IN ('a1', 'a2') THEN
    -- Efeitos do apuramento validados estruturalmente; linhas esperadas = lista ordenada completa (posição, tipo, descrição, cêntimos, evento).
    v_total := public._de333_cents(e->'total', NULL); v_sdate := public._de333_req(e, 'date')::date; PERFORM public._de333_req(e, 'number');
    IF jsonb_typeof(e->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(e->'lines') = 0
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(e->'lines') l WHERE jsonb_typeof(l->'line_type') IS DISTINCT FROM 'string' OR jsonb_typeof(l->'description') IS DISTINCT FROM 'string')
    THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
    SELECT jsonb_agg(jsonb_build_array((o - 1)::int, l->>'line_type', left(l->>'description', 160), public._de333_cents(l->'amount_cents', NULL), v_event, true) ORDER BY o)
      INTO v_exp FROM jsonb_array_elements(e->'lines') WITH ORDINALITY AS z(l, o);
  END IF;

  IF p_action = 'a1' THEN
    IF NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = v_office AND company_id = v_company AND type = 'ticket_office' AND is_active IS TRUE)
       OR NOT EXISTS (SELECT 1 FROM public.events WHERE id = v_event AND company_id = v_company)
    THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    IF EXISTS (SELECT 1 FROM public.ticket_office_settlements WHERE event_id = v_event AND company_id = v_company AND status = 'confirmed' AND reversed_at IS NULL)
    THEN RAISE EXCEPTION '#333: event_sealed' USING ERRCODE = 'P0001'; END IF;
    PERFORM pg_advisory_xact_lock(hashtext('de333:stmt:' || v_company::text || ':' || upper(btrim(e->>'number'))));
    IF EXISTS (SELECT 1 FROM public.ticket_office_statements WHERE company_id = v_company AND upper(btrim(number)) = upper(btrim(e->>'number')))
    THEN RAISE EXCEPTION '#333: duplicate_statement' USING ERRCODE = '23505'; END IF;
    INSERT INTO public.ticket_office_statements(company_id, financial_account_id, number, statement_date, document_total, status, created_by, notes)
    VALUES (v_company, v_office, btrim(e->>'number'), v_sdate, v_total::numeric / 100, 'draft', v_uid,
            '#333 assistente: revisão ' || a.review_id || ' v' || a.version) RETURNING id INTO v_st;
    INSERT INTO public.ticket_office_statement_lines(statement_id, company_id, line_type, position, description, amount, event_id)
    SELECT v_st, v_company, l->>'line_type', (o - 1)::int, left(l->>'description', 160), (l->>'amount_cents')::numeric / 100, v_event
    FROM jsonb_array_elements(e->'lines') WITH ORDINALITY AS z(l, o);
  ELSE
    SELECT (y.result->>'statement_id')::uuid INTO v_st FROM public.data_entry_assistant_executions_333 y WHERE y.authorization_id = a.id AND y.action_id = 'a1';
  END IF;

  IF p_action IN ('a1', 'a2') THEN
    -- Cabeçalho e linhas têm de ser EXATAMENTE os efeitos autorizados (a1: readback; a2: antes da RPC canónica, com locks).
    SELECT * INTO s FROM public.ticket_office_statements WHERE id = v_st FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    PERFORM 1 FROM public.ticket_office_statement_lines WHERE statement_id = v_st ORDER BY id FOR UPDATE;
    SELECT jsonb_agg(jsonb_build_array(l.position, l.line_type, l.description, round(l.amount * 100)::bigint, l.event_id,
             (l.company_id = v_company AND l.ticket_office_settlement_id IS NULL AND l.transaction_id IS NULL AND l.previous_statement_id IS NULL AND l.invoice_group_id IS NULL) IS TRUE)
           ORDER BY l.position, l.id)
      INTO v_act FROM public.ticket_office_statement_lines l WHERE l.statement_id = v_st;
    v_ok := s.company_id = v_company AND s.financial_account_id = v_office AND s.status = 'draft' AND s.number = btrim(e->>'number')
      AND s.statement_date = v_sdate AND round(s.document_total * 100) = v_total AND v_act = v_exp;
    IF v_ok IS NOT TRUE THEN
      RAISE EXCEPTION '#333: %', CASE WHEN p_action = 'a1' THEN 'readback_mismatch' ELSE 'data_changed' END USING ERRCODE = 'P0001'; END IF;
    IF p_action = 'a1' THEN
      res := jsonb_build_object('statement_id', v_st, 'number', btrim(e->>'number'), 'office_id', v_office, 'lines', jsonb_array_length(v_exp), 'sum_cents',
        (SELECT sum((x2->>3)::bigint) FROM jsonb_array_elements(v_exp) x2));
    ELSE
      PERFORM public.confirm_ticket_office_statement(v_st);
      IF NOT EXISTS (SELECT 1 FROM public.ticket_office_statements WHERE id = v_st AND status = 'confirmed') THEN RAISE EXCEPTION '#333: readback_mismatch' USING ERRCODE = 'P0001'; END IF;
      res := jsonb_build_object('statement_id', v_st, 'number', s.number, 'office_id', s.financial_account_id, 'status', 'confirmed');
    END IF;

  ELSIF p_action IN ('a4', 'a3') THEN
    c := e->'closing';
    IF jsonb_typeof(c) IS DISTINCT FROM 'object' OR c->>'office' IS DISTINCT FROM v_office::text OR c->>'event' IS DISTINCT FROM v_event::text
    THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
    PERFORM pg_advisory_xact_lock(hashtext('de333:close:' || v_office::text || ':' || v_event::text));
    v_gross := public._de333_closing_check(c, v_company);
    IF p_action = 'a4' THEN
      res := jsonb_build_object('event_id', v_event, 'deductions', jsonb_array_length(c->'deductions'), 'deductions_cents', (c->>'deductions_cents')::bigint,
        'gross_cents', round(v_gross * 100), 'net_cents', (c->>'net_cents')::bigint, 'writes', 0);
    ELSE
      SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
      v_set := (public.save_ticket_office_settlement(NULL,
        jsonb_build_object('financial_account_id', v_office, 'event_id', v_event, 'settlement_date', c->>'settlement_date',
          'gross_revenue', v_gross, 'total_deductions', (c->>'deductions_cents')::numeric / 100, 'net_calculated', (c->>'net_cents')::numeric / 100,
          'net_adjusted', null, 'net_transferred', 0, 'transfer_account_id', null, 'venue_retained_amount', 0, 'venue_retained_invoice_id', null,
          'venue_invoice_remainder_paid', false, 'venue_invoice_remainder_amount', 0,
          'notes', '#333 assistente: revisão ' || a.review_id || ' v' || a.version, 'conciliated_by', coalesce(v_email, 'system')),
        true,
        (SELECT coalesce(jsonb_agg(jsonb_build_object('id', d->>'id', 'paid_amount', (d->>'gross_cents')::numeric / 100)), '[]'::jsonb) FROM jsonb_array_elements(c->'deductions') d),
        jsonb_build_object('amount', (c->>'net_cents')::numeric / 100, 'to_account_id', c->>'transfer_account', 'credited', false),
        NULL, NULL, coalesce(v_email, v_uid::text)) ->> 'settlement_id')::uuid;
      SELECT * INTO s FROM public.ticket_office_settlements WHERE id = v_set;
      IF NOT FOUND OR (s.status = 'confirmed' AND s.company_id = v_company AND round(s.net_transferred * 100) = (c->>'net_cents')::bigint
         AND s.transfer_account_id = (c->>'transfer_account')::uuid AND s.transfer_transaction_id IS NOT NULL
         AND round(s.total_deductions * 100) = (c->>'deductions_cents')::bigint AND round(s.net_calculated * 100) = (c->>'net_cents')::bigint) IS NOT TRUE
      THEN RAISE EXCEPTION '#333: readback_mismatch' USING ERRCODE = 'P0001'; END IF;
      SELECT operation_key INTO v_key FROM public.transactions WHERE id = s.transfer_transaction_id;
      SELECT count(*) FILTER (WHERE (status = 'pending' AND paid_amount = 0 AND round(amount * 100) = (c->>'net_cents')::bigint AND company_id = v_company) IS TRUE), count(*)
        INTO v_legs, v_n FROM public.transactions WHERE operation_key = v_key;
      SELECT count(*) FILTER (WHERE (t2.settlement_id = v_set AND t2.status = 'paid' AND round(t2.paid_amount * 100) = (d->>'gross_cents')::bigint
           AND round((SELECT sum(p.amount) FROM public.transaction_payments p WHERE p.transaction_id = t2.id AND p.status = 'paid' AND p.reversed_at IS NULL) * 100) = (d->>'gross_cents')::bigint) IS NOT TRUE)
        INTO v_bad FROM jsonb_array_elements(c->'deductions') d LEFT JOIN public.transactions t2 ON t2.id = (d->>'id')::uuid;
      IF v_key IS NULL OR v_legs IS DISTINCT FROM 2 OR v_n IS DISTINCT FROM 2 OR v_bad IS DISTINCT FROM 0 THEN RAISE EXCEPTION '#333: readback_mismatch' USING ERRCODE = 'P0001'; END IF;
      res := jsonb_build_object('settlement_id', v_set, 'event_id', v_event, 'office_id', v_office, 'net_cents', (c->>'net_cents')::bigint,
        'transfer_transaction_id', s.transfer_transaction_id, 'operation_key', v_key, 'deductions', jsonb_array_length(c->'deductions'));
    END IF;

  ELSIF p_action = 'a5' THEN
    IF jsonb_typeof(e->'settlement') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
    IF (public.has_role(v_uid, 'admin') OR public.is_platform_admin(v_uid) OR public.has_permission(v_uid, 'manage_accounts')) IS NOT TRUE
    THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    v_total := public._de333_cents(e->'settlement'->'amount_cents', 1); v_amount := v_total::numeric / 100;
    v_date := public._de333_req(e->'settlement', 'date')::date; v_to := public._de333_req(e->'settlement', 'account')::uuid;
    IF (v_date > (now() AT TIME ZONE 'Europe/Lisbon')::date) IS NOT FALSE THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    IF 'a3' = ANY (a.action_ids) THEN
      -- Fecho gravado por esta autorização: a referência é o plano revisto (closing) e o resultado conferido de a3.
      SELECT (y.result->>'settlement_id')::uuid INTO v_set FROM public.data_entry_assistant_executions_333 y WHERE y.authorization_id = a.id AND y.action_id = 'a3';
      IF jsonb_typeof(e->'closing') IS DISTINCT FROM 'object' OR public._de333_req(e->'closing', 'transfer_account')::uuid IS DISTINCT FROM v_to
         OR public._de333_cents(e->'closing'->'net_cents', 1) IS DISTINCT FROM v_total
      THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
      SELECT * INTO s FROM public.ticket_office_settlements WHERE id = v_set AND company_id = v_company FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    ELSE
      IF jsonb_typeof(e->'canonical') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
      SELECT * INTO s FROM public.ticket_office_settlements WHERE event_id = v_event AND company_id = v_company AND status = 'confirmed' AND reversed_at IS NULL FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
      IF (s.transfer_account_id = public._de333_req(e->'canonical', 'transfer_account_id')::uuid
          AND round(s.net_transferred * 100) = public._de333_cents(e->'canonical'->'net_transferred_cents', 1)) IS NOT TRUE
      THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    END IF;
    IF (s.status = 'confirmed' AND s.reversed_at IS NULL AND s.transfer_transaction_id IS NOT NULL AND s.event_id = v_event AND s.company_id = v_company
        AND s.financial_account_id = v_office AND s.transfer_account_id = v_to AND round(s.net_transferred * 100) = v_total AND v_date >= s.settlement_date) IS NOT TRUE
    THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    -- Contas ativas da empresa NO MOMENTO (bilheteira e conta de destino).
    IF NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = s.financial_account_id AND company_id = v_company AND type = 'ticket_office' AND is_active IS TRUE)
       OR NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = v_to AND company_id = v_company AND is_active IS TRUE AND type IN ('bank','cash','venue'))
    THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    SELECT * INTO t FROM public.transactions WHERE id = s.transfer_transaction_id AND company_id = v_company;
    IF NOT FOUND OR (t.operation_key LIKE 'TRF-FECHO-%') IS NOT TRUE THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    v_key := t.operation_key;
    PERFORM 1 FROM public.transactions WHERE operation_key = v_key ORDER BY id FOR UPDATE;
    PERFORM 1 FROM public.transaction_payments p JOIN public.transactions x0 ON x0.id = p.transaction_id WHERE x0.operation_key = v_key ORDER BY p.id FOR UPDATE OF p;
    -- Integridade do par TRF-FECHO (create_settlement_transfer), fail-closed: qualquer campo NULL/diferente conta como inválido.
    SELECT count(*), count(*) FILTER (WHERE (
      x2.company_id = v_company AND x2.event_id = s.event_id AND x2.amount = v_amount AND x2.iva_rate = 0 AND x2.reversed_at IS NULL
      AND x2.exclude_from_result AND x2.payment_method = 'transfer' AND x2.currency = 'EUR'
      AND ((x2.type = 'expense' AND x2.id = s.transfer_transaction_id AND x2.account_id = s.financial_account_id AND x2.settlement_id = s.id)
        OR (x2.type = 'income' AND x2.id <> s.transfer_transaction_id AND x2.account_id = s.transfer_account_id AND x2.settlement_id IS NULL))) IS NOT TRUE)
      INTO v_legs, v_bad FROM public.transactions x2 WHERE x2.operation_key = v_key;
    IF v_legs IS DISTINCT FROM 2 OR v_bad IS DISTINCT FROM 0 OR (SELECT count(DISTINCT type) FROM public.transactions WHERE operation_key = v_key) IS DISTINCT FROM 2
    THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    -- Por perna: liquidada EXATAMENTE como a evidência (1 pagamento, pago, valor, data, conta da perna, empresa, transferência, sem estorno)
    -- vs. limpa (pendente, 0 pago, sem pagamentos). Qualquer outro estado (pago com data/conta/valor divergente, estorno, planeado) não se adivinha.
    SELECT count(*) FILTER (WHERE (x3.status = 'paid' AND x3.paid_amount = v_amount AND x3.payment_date = v_date
             AND (SELECT count(*) FROM public.transaction_payments p WHERE p.transaction_id = x3.id) = 1
             AND EXISTS (SELECT 1 FROM public.transaction_payments p WHERE p.transaction_id = x3.id AND p.status = 'paid' AND p.amount = v_amount
               AND p.payment_date = v_date AND p.account_id = x3.account_id AND p.company_id = v_company AND p.payment_method = 'transfer' AND p.reversed_at IS NULL)) IS TRUE),
           count(*) FILTER (WHERE (x3.status IN ('pending','approved') AND x3.paid_amount = 0 AND x3.payment_date IS NULL
             AND NOT EXISTS (SELECT 1 FROM public.transaction_payments p WHERE p.transaction_id = x3.id)) IS TRUE),
           count(*) FILTER (WHERE x3.status IS NOT DISTINCT FROM 'paid')
      INTO v_paid, v_n, v_div FROM public.transactions x3 WHERE x3.operation_key = v_key;
    IF v_paid = 2 THEN
      res := jsonb_build_object('settlement_id', s.id, 'transfer_transaction_id', t.id, 'operation_key', v_key, 'already_liquidated', true, 'writes', 0,
        'payment_date', v_date, 'amount_cents', v_total);
    ELSIF v_n = 2 THEN
      UPDATE public.transactions SET status = 'paid', payment_date = v_date, paid_amount = amount WHERE operation_key = v_key;
      SELECT count(*) FILTER (WHERE (x4.status = 'paid' AND x4.paid_amount = v_amount AND x4.payment_date = v_date
        AND (SELECT count(*) FROM public.transaction_payments p WHERE p.transaction_id = x4.id) = 1
        AND EXISTS (SELECT 1 FROM public.transaction_payments p WHERE p.transaction_id = x4.id AND p.status = 'paid' AND p.amount = v_amount
          AND p.payment_date = v_date AND p.account_id = x4.account_id AND p.company_id = v_company AND p.payment_method = 'transfer' AND p.reversed_at IS NULL)) IS NOT TRUE), count(*)
        INTO v_bad, v_legs FROM public.transactions x4 WHERE x4.operation_key = v_key;
      IF v_bad IS DISTINCT FROM 0 OR v_legs IS DISTINCT FROM 2 THEN RAISE EXCEPTION '#333: readback_mismatch' USING ERRCODE = 'P0001'; END IF;
      res := jsonb_build_object('settlement_id', s.id, 'transfer_transaction_id', t.id, 'operation_key', v_key, 'already_liquidated', false,
        'payment_date', v_date, 'amount_cents', v_total, 'writes', 2, 'payments', 2);
    ELSIF v_div = 2 THEN
      -- Crédito preexistente que NÃO corresponde à evidência autorizada: nunca se atribui como sucesso.
      RAISE EXCEPTION '#333: liquidated_divergent' USING ERRCODE = 'P0001';
    ELSE
      RAISE EXCEPTION '#333: partial_state_manual' USING ERRCODE = 'P0001';
    END IF;
  ELSE RAISE EXCEPTION '#333: action_not_authorized' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.data_entry_assistant_executions_333(authorization_id, action_id, owner_id, company_id, effects_hash, result)
  VALUES (a.id, p_action, v_uid, v_company, a.effects_hash, res) RETURNING * INTO ex;
  RETURN jsonb_build_object('action_id', p_action, 'status', ex.status, 'replayed', false, 'result', ex.result);
END $function$

CREATE OR REPLACE FUNCTION public.sync_partner_aporte_mirror()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_src       record;
  v_acc       record;
  v_partner   record;
  v_cat_id    uuid;
  v_amount    numeric := 0;
  v_bridge_id uuid;
  v_aporte_id uuid;
  v_ret       record;
begin
  if TG_OP = 'DELETE' then v_src := OLD; else v_src := NEW; end if;
  if TG_OP = 'DELETE' then v_ret := OLD; else v_ret := NEW; end if;

  -- Só despesas geram aporte. O aporte espelhado e receita, logo nunca se espelha a si proprio.
  if v_src.type is distinct from 'expense' then
    return v_ret;
  end if;

  select id, aporte_transaction_id into v_bridge_id, v_aporte_id
    from partner_aporte_mirror
   where source_transaction_id = v_src.id;

  if TG_OP <> 'DELETE' then
    select * into v_acc from financial_accounts where id = NEW.account_id;
    if v_acc.id is not null
       and coalesce(v_acc.mirror_partner_aporte, false)
       and v_acc.partner_id is not null
       and NEW.status = 'paid'
       and NEW.reversed_at is null
    then
      v_amount := coalesce(NEW.paid_amount, 0);
    end if;
  end if;

  -- Nada a fazer
  if v_amount <= 0 and v_bridge_id is null then
    return v_ret;
  end if;

  -- Deixou de haver aporte: apagar o espelho (a ponte e o movimento de capital caem por cascata)
  if v_amount <= 0 then
    delete from transactions where id = v_aporte_id;
    return v_ret;
  end if;

  select * into v_partner from event_partners where id = v_acc.partner_id;
  select id into v_cat_id from account_categories
   where company_id = NEW.company_id and code = '10.1.01' limit 1;
  if v_cat_id is null then
    raise exception 'Conta-espelho: rubrica 10.1.01 nao existe na empresa %', NEW.company_id;
  end if;

  if v_bridge_id is null then
    insert into transactions (
      company_id, type, description, amount, paid_amount, iva_rate,
      date, payment_date, status, account_id, event_id, supplier_id,
      category_id, payment_method
    ) values (
      NEW.company_id, 'income',
      'Aporte automatico — ' || NEW.description,
      v_amount, v_amount, 0,
      coalesce(NEW.payment_date, NEW.date), coalesce(NEW.payment_date, NEW.date), 'paid',
      NEW.account_id, v_partner.event_id, v_partner.supplier_id,
      v_cat_id, 'transfer'
    ) returning id into v_aporte_id;

    insert into partner_aporte_mirror
      (company_id, account_id, source_transaction_id, aporte_transaction_id)
    values (NEW.company_id, NEW.account_id, NEW.id, v_aporte_id);

    insert into partner_capital_moves
      (company_id, event_id, partner_id, transaction_id, kind, flow)
    values (NEW.company_id, v_partner.event_id, v_acc.partner_id, v_aporte_id,
            'aporte', 'partner_settlement');
  else
    update transactions set
      description  = 'Aporte automatico — ' || NEW.description,
      amount       = v_amount,
      paid_amount  = v_amount,
      date         = coalesce(NEW.payment_date, NEW.date),
      payment_date = coalesce(NEW.payment_date, NEW.date),
      account_id   = NEW.account_id,
      event_id     = v_partner.event_id,
      supplier_id  = v_partner.supplier_id,
      updated_at   = now()
    where id = v_aporte_id;

    update partner_aporte_mirror
       set account_id = NEW.account_id, updated_at = now()
     where id = v_bridge_id;
  end if;

  return v_ret;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_shared_cost_mirror()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_src        record;
  v_ret        record;
  v_bridge_id  uuid;
  v_mirror_id  uuid;
  v_amount     numeric := 0;
  v_cat_id     uuid;
begin
  if TG_OP = 'DELETE' then v_src := OLD; v_ret := OLD; else v_src := NEW; v_ret := NEW; end if;

  -- Guarda anti-recursao: o proprio espelho nunca dispara logica de espelho.
  if exists (select 1 from shared_cost_mirror where mirror_transaction_id = v_src.id) then
    return v_ret;
  end if;

  select id, mirror_transaction_id into v_bridge_id, v_mirror_id
    from shared_cost_mirror
   where source_transaction_id = v_src.id;

  if TG_OP <> 'DELETE'
     and NEW.type = 'expense'
     and NEW.shared_cost_account_id is not null
     and NEW.status = 'paid'
     and NEW.reversed_at is null
  then
    v_amount := coalesce(NEW.paid_amount, 0);
  end if;

  -- Nada a fazer
  if v_amount <= 0 and v_bridge_id is null then
    return v_ret;
  end if;

  -- Deixou de haver adiantamento: apagar o espelho (a ponte cai por cascata)
  if v_amount <= 0 then
    delete from transactions where id = v_mirror_id;
    return v_ret;
  end if;

  select id into v_cat_id from account_categories
   where company_id = NEW.company_id and code = '10.12.01' limit 1;
  if v_cat_id is null then
    raise exception 'Custo partilhado: rubrica 10.12.01 nao existe na empresa %', NEW.company_id;
  end if;

  if v_bridge_id is null then
    insert into transactions (
      company_id, type, description, amount, paid_amount, iva_rate,
      date, payment_date, status, account_id, event_id, supplier_id,
      category_id, payment_method, exclude_from_result
    ) values (
      NEW.company_id, 'income',
      'Adiantamento por conta de terceiros — ' || coalesce(NEW.description, ''),
      v_amount, v_amount, 0,
      NEW.date, NEW.payment_date, 'paid',
      NEW.shared_cost_account_id, null, NEW.shared_cost_counterparty_id,
      v_cat_id, 'transfer', true
    ) returning id into v_mirror_id;

    insert into shared_cost_mirror
      (company_id, account_id, source_transaction_id, mirror_transaction_id)
    values (NEW.company_id, NEW.shared_cost_account_id, NEW.id, v_mirror_id);
  else
    update transactions set
      description  = 'Adiantamento por conta de terceiros — ' || coalesce(NEW.description, ''),
      amount       = v_amount,
      paid_amount  = v_amount,
      date         = NEW.date,
      payment_date = NEW.payment_date,
      account_id   = NEW.shared_cost_account_id,
      supplier_id  = NEW.shared_cost_counterparty_id,
      updated_at   = now()
    where id = v_mirror_id;

    update shared_cost_mirror
       set account_id = NEW.shared_cost_account_id, updated_at = now()
     where id = v_bridge_id;
  end if;

  return v_ret;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_settlement_transfer(p_settlement_id uuid, p_from_account_id uuid, p_to_account_id uuid, p_amount numeric, p_date date, p_credited boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid;
  v_settlement record;
  v_from_name text;
  v_to_name text;
  v_key text;
  v_desc text;
  v_out uuid;
  v_status text;
  v_paid numeric;
  v_pay_date date;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF NOT (
      public.has_role(auth.uid(), 'admin')
      OR public.is_platform_admin(auth.uid())
      OR public.has_permission(auth.uid(), 'manage_accounts')
    ) THEN
      RAISE EXCEPTION 'Sem permissão para lançar a transferência do fecho' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_company := public.current_company_id();
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Empresa activa não resolvida' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_settlement FROM public.ticket_office_settlements WHERE id = p_settlement_id;

  IF v_settlement.id IS NULL THEN
    RAISE EXCEPTION 'Fecho não encontrado' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_settlement.company_id IS DISTINCT FROM v_company THEN
    RAISE EXCEPTION 'Fecho de outra empresa' USING ERRCODE = '42501';
  END IF;
  IF v_settlement.transfer_transaction_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este fecho já tem transferência lançada' USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Valor da transferência tem de ser positivo' USING ERRCODE = '22023';
  END IF;
  IF p_from_account_id IS NULL OR p_to_account_id IS NULL THEN
    RAISE EXCEPTION 'Contas de origem e destino são obrigatórias' USING ERRCODE = '22023';
  END IF;
  IF p_from_account_id = p_to_account_id THEN
    RAISE EXCEPTION 'Conta de origem e destino não podem ser a mesma' USING ERRCODE = '22023';
  END IF;

  SELECT name INTO v_from_name FROM public.financial_accounts WHERE id = p_from_account_id;
  SELECT name INTO v_to_name FROM public.financial_accounts WHERE id = p_to_account_id;

  v_key := 'TRF-FECHO-' || upper(substring(replace(p_settlement_id::text, '-', '') FROM 1 FOR 8));
  v_desc := 'Transferência fecho bilheteira ' || coalesce(v_from_name, '?')
            || ' -> ' || coalesce(v_to_name, '?')
            || CASE WHEN p_credited THEN '' ELSE ' (a receber)' END;

  IF p_credited THEN
    v_status := 'paid'; v_paid := p_amount; v_pay_date := p_date;
  ELSE
    v_status := 'pending'; v_paid := 0; v_pay_date := NULL;
  END IF;

  INSERT INTO public.transactions (
    company_id, event_id, type, category_id, description, amount, iva_rate, date,
    status, paid_amount, payment_date, account_id, payment_method,
    exclude_from_result, currency, settlement_id, operation_key
  ) VALUES (
    v_company, v_settlement.event_id, 'expense', 'b32df086-c995-4747-a3f9-bfefa0063d0a',
    v_desc, p_amount, 0, p_date,
    v_status, v_paid, v_pay_date, p_from_account_id, 'transfer',
    true, 'EUR', p_settlement_id, v_key
  ) RETURNING id INTO v_out;

  INSERT INTO public.transactions (
    company_id, event_id, type, category_id, description, amount, iva_rate, date,
    status, paid_amount, payment_date, account_id, payment_method,
    exclude_from_result, currency, settlement_id, operation_key
  ) VALUES (
    v_company, v_settlement.event_id, 'income', 'b32df086-c995-4747-a3f9-bfefa0063d0a',
    v_desc, p_amount, 0, p_date,
    v_status, v_paid, v_pay_date, p_to_account_id, 'transfer',
    true, 'EUR', NULL, v_key
  );

  UPDATE public.ticket_office_settlements
  SET transfer_transaction_id = v_out,
      net_transferred = p_amount,
      transfer_account_id = p_to_account_id
  WHERE id = p_settlement_id;

  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_ticket_office_settlement(p_settlement_id uuid, p_reason text, p_caller_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_s record;
  v_key text;
  v_exp uuid[];
  v_n int;
  v_counts jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão em falta' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_role(v_uid, 'admin') OR public.is_platform_admin()) THEN
    RAISE EXCEPTION 'Só um admin pode estornar um fecho de bilheteira.' USING ERRCODE = '42501';
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'Motivo do estorno obrigatório' USING ERRCODE = '22023'; END IF;

  SELECT * INTO v_s FROM ticket_office_settlements WHERE id = p_settlement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fecho não encontrado' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.row_belongs_to_current_company(v_s.company_id) THEN RAISE EXCEPTION 'Fecho de outra empresa' USING ERRCODE = '42501'; END IF;
  IF v_s.status = 'reversed' THEN RAISE EXCEPTION 'Fecho já estornado' USING ERRCODE = 'P0001'; END IF;

  IF v_s.transfer_transaction_id IS NOT NULL THEN
    SELECT operation_key INTO v_key FROM transactions WHERE id = v_s.transfer_transaction_id;
    UPDATE ticket_office_settlements SET transfer_transaction_id = NULL WHERE id = p_settlement_id;
    IF v_key IS NOT NULL THEN
      DELETE FROM transactions WHERE operation_key = v_key;
    ELSE
      DELETE FROM transactions WHERE id = v_s.transfer_transaction_id;
    END IF;
    GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('transfer_legs', v_n);
  END IF;

  SELECT coalesce(array_agg(id), '{}') INTO v_exp FROM transactions WHERE settlement_id = p_settlement_id AND type = 'expense';
  DELETE FROM transaction_payments WHERE transaction_id = ANY(v_exp);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('payments', v_n);
  UPDATE transactions SET settlement_id = NULL, status = 'pending', payment_date = NULL, paid_amount = 0, account_id = NULL
   WHERE id = ANY(v_exp);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('expenses', v_n);

  UPDATE event_ticket_office_advances SET settlement_id = NULL WHERE settlement_id = p_settlement_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('advances', v_n);

  UPDATE ticket_office_settlements SET status = 'reversed', reversed_at = now(), reversed_by = v_uid,
         reversal_reason = p_reason, transfer_transaction_id = NULL, net_transferred = 0, transfer_account_id = NULL
   WHERE id = p_settlement_id;

  UPDATE event_ticket_office_assignments SET is_conciliated = false, conciliated_at = NULL, conciliated_by = NULL
   WHERE event_id = v_s.event_id AND financial_account_id = v_s.financial_account_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('assignments', v_n);

  INSERT INTO system_audit_log (entity_type, entity_id, action, changed_by, metadata, company_id)
  VALUES ('ticket_office_settlement', p_settlement_id::text, 'reverse', coalesce(nullif(trim(p_caller_name), ''), v_uid::text),
          jsonb_build_object('reason', p_reason, 'counts', v_counts), v_s.company_id);

  RETURN jsonb_build_object('settlement_id', p_settlement_id, 'counts', v_counts);
END $function$
